/* v5.4.18 · MY course card auto-heal
   Single common rule: if a lesson exists in MY_CLASS_LESSONS but its HOME card is missing,
   create the card from MY_CLASS_META and lesson counts. This prevents future data/card drift. */
function ensureMyClassHomeCards(){
  const section=document.querySelector('#homePage .myClassSection');
  if(!section||typeof MY_CLASS_LESSONS!=='object')return;
  const badgeMap={11:'9/28',12:'9/8–17',13:'Pattern',14:'10/1'};
  const titleMap={11:'Life Story, Past Experience & Active Chunks',12:'Teacher Patterns & Missing Chunks',13:'not as ~ as it used to be',14:'Natural Conversation & AI Discussion'};
  const descMap={
    11:'9월 28일 실제 수업의 장거리 운전·어린 시절 역할·진학과 경력·인생 회고 표현을 Chunk 중심으로 복습합니다.',
    12:'9/8·9/10·9/15·9/17 수업에서 선생님이 강조했지만 SAYWARD에 빠져 있던 핵심 표현만 중복 없이 보강합니다.',
    13:'예전과 지금을 비교하는 not as ~ as ... used to be 꼬리 구조를 반복 훈련합니다.',
    14:'10월 1일 실제 수업의 자연스러운 회화 패턴과 AI 토론 표현, touch base를 반복 훈련합니다.'
  };
  Object.keys(MY_CLASS_LESSONS).map(Number).filter(Number.isFinite).sort((a,b)=>a-b).forEach(n=>{
    if(section.querySelector('#myClassLesson'+n+'Card'))return;
    const d=MY_CLASS_LESSONS[n]||{},m=MY_CLASS_META?.[n]||{};
    const card=document.createElement('div');
    card.className='myClassCard'; card.id='myClassLesson'+n+'Card';
    card.setAttribute('role','button');card.setAttribute('tabindex','0');card.style.marginTop='10px';
    card.dataset.studyCourse='my';card.dataset.studyLesson=String(n);
    card.addEventListener('click',()=>studyDirectOpenCourse('my',n));
    const corrections=Array.isArray(d.corrections)?d.corrections.length:0;
    const chunks=Array.isArray(d.chunks)?d.chunks.length:0;
    const speaking=Array.isArray(d.speaking)?d.speaking.length:0;
    const habits=Array.isArray(d.habits)?d.habits.length:0;
    const safeTitle=titleMap[n]||String(m.title||('MY 수업 '+n)).replace(/^Sep\s*[^·]*·\s*/,'');
    const safeDesc=descMap[n]||String(m.sub||'MY 수업 복습');
    const badge=badgeMap[n]||'';
    card.innerHTML='<label class="myLessonSelectMini" onclick="event.stopPropagation()">'+
      '<input class="myClassSelectCheck" type="checkbox" data-my-lesson="'+n+'" onclick="event.stopPropagation()" aria-label="수업 '+n+' 전체 반복 선택"><span>선택</span></label>'+
      '<div class="myClassTop"><b>MY 수업 · 수업 '+n+'</b><span class="myClassBadge">NEW'+(badge?' · '+badge:'')+'</span></div>'+
      '<div class="myClassTitle"></div><div class="myClassDesc"></div><div class="myClassMeta">'+
      '<span>✅ 핵심 교정 '+corrections+'</span><span>🧩 Chunk '+chunks+'</span><span>🗣 말하기 '+speaking+'</span>'+(habits?'<span>⚠ 습관 '+habits+'</span>':'')+'</div>';
    card.querySelector('.myClassTitle').textContent=safeTitle;
    card.querySelector('.myClassDesc').textContent=safeDesc;
    section.appendChild(card);
  });
}

