function myClassEsc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function mvSplitStudySentences280(text,{korean=false}={}){
  const raw=String(text||'').replace(/\s+/g,' ').trim();
  if(!raw)return [];
  const enders=korean?'.!?。！？':'.!?';
  const closers='\"\'’”)]}〉》」』';
  const out=[];
  let start=0;
  const isLatinLower=c=>/[a-z]/.test(c||'');
  const isDigit=c=>/[0-9]/.test(c||'');
  const isEnd=c=>enders.includes(c);
  for(let i=0;i<raw.length;i++){
    const c=raw[i];
    if(!isEnd(c))continue;

    // Decimal numbers such as 2.5 are not sentence boundaries.
    if(c==='.'&&isDigit(raw[i-1])&&isDigit(raw[i+1]))continue;

    // Initials/abbreviations such as U.S. / a.m. / p.m. are kept together.
    if(c==='.'&&/[A-Za-z]/.test(raw[i-1]||'')&&/[A-Za-z]/.test(raw[i+1]||''))continue;

    let j=i+1;
    while(j<raw.length&&isEnd(raw[j]))j++;
    const afterPunc=j;
    while(j<raw.length&&closers.includes(raw[j]))j++;

    // Korean quoted-question suffix: ...?라고 / ...?라고는 / ...?라는 등.
    if(korean&&j<raw.length&&!/\s/.test(raw[j])&&/[가-힣]/.test(raw[j]))continue;

    let k=j;
    while(k<raw.length&&/\s/.test(raw[k]))k++;
    if(k>=raw.length){
      out.push(raw.slice(start,raw.length).trim());
      start=raw.length;
      break;
    }

    // A period before a lower-case continuation is usually an abbreviation, not a stop.
    if(c==='.'&&isLatinLower(raw[k]))continue;

    // If there was no whitespace/closing quote after punctuation, keep scanning.
    if(j===afterPunc && afterPunc<raw.length && !/\s/.test(raw[afterPunc]))continue;

    out.push(raw.slice(start,j).trim());
    start=k;
    i=k-1;
  }
  if(start<raw.length)out.push(raw.slice(start).trim());
  return out.filter(Boolean);
}
function myClassSplitSentences(text){return mvSplitStudySentences280(text,{korean:false});}
function myClassSplitKoSentences(text){return mvSplitStudySentences280(text,{korean:true});}
