function myClassHighlightSpeakingSentence(el){
  document.querySelectorAll('.mySpeakSentence').forEach(x=>{
    x.classList.remove('myClassSentenceNow');
    x.style.removeProperty('background');
    x.style.removeProperty('background-color');
    x.style.removeProperty('color');
    x.style.removeProperty('box-shadow');
    x.style.removeProperty('font-weight');
    x.style.removeProperty('border-radius');
    x.style.removeProperty('padding');
  });

  if(!el)return;

  el.classList.add('myClassSentenceNow');

  // CSS cascade에 의존하지 않고 현재 문장에 직접 배경색을 칠한다.
  el.style.setProperty('background','#e9e5ff','important');
  el.style.setProperty('background-color','#e9e5ff','important');
  el.style.setProperty('color','#241a72','important');
  el.style.setProperty('box-shadow','0 0 0 2px rgba(99,102,241,.20)','important');
  el.style.setProperty('font-weight','900','important');
  el.style.setProperty('border-radius','8px','important');
  el.style.setProperty('padding','2px 4px','important');

  try{
    el.scrollIntoView({behavior:'smooth',block:'center',inline:'nearest'});
  }catch(e){}
}

