function myClassBadMarked229(text,marks,why){
  text=String(text||'');
  let safe=(Array.isArray(marks)?marks:[]).map(m=>({start:Math.max(0,Number(m.start)||0),end:Math.min(text.length,Number(m.end)||0)})).filter(m=>m.end>m.start).sort((a,b)=>a.start-b.start);
  const cue=String(why||'').match(/^`([^`]+)`\s*(?:→|삭제)/);
  if(cue&&safe.length)safe=safe.filter(m=>text.slice(m.start,m.end)===cue[1]);
  if(!safe.length)return myClassEsc(text);
  let out='',pos=0;
  safe.forEach(m=>{if(m.start<pos)return;out+=myClassEsc(text.slice(pos,m.start));out+='<mark class="myStudyBadMark229">'+myClassEsc(text.slice(m.start,m.end))+'</mark>';pos=m.end;});
  out+=myClassEsc(text.slice(pos));return out;
}
function myClassRuleText229(text){
  const s=String(text||'');let out='',pos=0,m;const rx=/`([^`]+)`/g;
  while((m=rx.exec(s))){out+=myClassEsc(s.slice(pos,m.index));out+='<span class="myStudyRuleToken229">'+myClassEsc(m[1])+'</span>';pos=rx.lastIndex;}
  out+=myClassEsc(s.slice(pos));return out;
}

