/* ===== V5.3.280 · SPEAKING KOREAN/ENGLISH PAIRING STANDARD =====
   Never pair a Korean summary/instruction with an English answer sentence by array index.
   MY / SORI / OPIC / FRIENDS all use the same safe sentence-pairing rule.
*/
function studySpeakingKoIsSummary280(text){
  const s=String(text||'').trim();
  return /위 핵심|전체 답변의 흐름|AL 수준으로 답해|모범답안|활용해 전체 답변/.test(s);
}
function studySpeakingMatchTokens280(text){
  return String(text||'').toLowerCase()
    .replace(/[’‘]/g,"'")
    .replace(/\b(well|actually|you know|so|overall|personally|basically|for example|of course|in the end|looking back)\b/g,' ')
    .replace(/[^a-z0-9']+/g,' ')
    .replace(/\s+/g,' ').trim().split(' ').filter(x=>x.length>1);
}
function studySpeakingSimilarity280(a,b){
  const A=new Set(studySpeakingMatchTokens280(a)),B=new Set(studySpeakingMatchTokens280(b));
  if(!A.size||!B.size)return 0;
  let hit=0; A.forEach(x=>{if(B.has(x))hit++});
  return (2*hit)/(A.size+B.size);
}
function studySpeakingReferenceRows280(data){
  const rows=[];
  (data?.corrections||[]).forEach(x=>{if(x?.en&&x?.ko)rows.push({en:x.en,ko:x.ko,kind:'correction'});});
  (data?.chunks||[]).forEach(x=>{const ko=x?.exampleKo||'';if(x?.example&&ko)rows.push({en:x.example,ko,kind:'chunk'});});
  return rows;
}
function studySpeakingAlignedKoSentences280(item,data){
  const ens=myClassSplitSentences(item?.text||'');
  if(!ens.length)return [];
  if(Array.isArray(item?.koSentences)&&item.koSentences.length===ens.length){
    return item.koSentences.map(x=>String(x||'').trim());
  }
  const rawKo=String(item?.ko||'').trim();
  const kos=myClassSplitKoSentences(rawKo);
  if(rawKo&&!studySpeakingKoIsSummary280(rawKo)&&kos.length===ens.length){
    return kos;
  }
  const refs=studySpeakingReferenceRows280(data);
  return ens.map(en=>{
    let best=null;
    for(const r of refs){
      const score=studySpeakingSimilarity280(en,r.en);
      if(!best||score>best.score)best={...r,score};
    }
    // Deliberately conservative: a missing Korean cue is better than a wrong one.
    return best&&best.score>=0.80?best.ko:'';
  });
}
window.studySpeakingAlignedKoSentences280=studySpeakingAlignedKoSentences280;

