function packKey(name){return `mv_${currentPack}_${name}`}
function selectedDaysKey(){return `mv_${currentPack}_selectedStudyDays`}
function selectedRepeatKey(){return `mv_${currentPack}_selectedStudyRepeat`}
function selectedStudyModeKey(){return `mv_${currentPack}_selectedStudyMode`}
function ensureStats(){
  ALL_WORDS.forEach(w=>{
    if(!stats[w.word])stats[w.word]={miss:0,streak:0,lastMiss:0,lastSeen:0,quizWrong:0,quizCorrect:0,quizStreak:0,lastQuizWrong:0,studyCount:0,reviewStep:0,dueAt:0};
    const st=stats[w.word];
    if(st.quizWrong==null)st.quizWrong=0;if(st.quizCorrect==null)st.quizCorrect=0;if(st.lastQuizWrong==null)st.lastQuizWrong=0;
    if(st.studyCount==null)st.studyCount=0;if(st.reviewStep==null)st.reviewStep=0;if(st.dueAt==null)st.dueAt=0;
  });
}
function loadPackState(){
  known=mvStorage.json(packKey('known'),[]);
  favs=mvStorage.json(packKey('favs'),[]);
  stats=mvStorage.json(packKey('stats'),{});
  if(!Array.isArray(known))known=[];
  if(!Array.isArray(favs))favs=[];
  if(!stats||typeof stats!=='object'||Array.isArray(stats))stats={};
  ensureStats();
}
function save(){
  mvStorage.set(packKey('known'),JSON.stringify(known));
  mvStorage.set(packKey('favs'),JSON.stringify(favs));
  mvStorage.set(packKey('stats'),JSON.stringify(stats));
  if($('orderMode'))mvStorage.set(packKey('order'),$('orderMode').value);
  if($('speechMode'))mvStorage.set(packKey('speech'),$('speechMode').value);
}
loadPackState();
function missClass(n){return n>=5?'fire':n>=3?'hot':n>=1?'warm':''}
function escHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const __saywardEntityRx=/&(?:#x?[0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]+);/;
const __saywardEntityDecoder=document.createElement('textarea');
const __saywardDecodedObjects=new WeakSet();
function decodeHtmlEntities(value){
  let text=String(value??'');
  if(!__saywardEntityRx.test(text))return text;
  const el=__saywardEntityDecoder;
  // 일부 CSV 데이터는 &amp;#39;처럼 두 번 이상 인코딩되어 있으므로
  // 화면과 TTS에 엔티티가 남지 않을 때까지 안전하게 반복 해제한다.
  for(let n=0;n<6 && __saywardEntityRx.test(text);n++){
    el.innerHTML=text;
    const decoded=el.value;
    if(decoded===text)break;
    text=decoded;
  }
  return text;
}
function decodeDataEntities(value){
  if(value&&typeof value==='object'){
    if(__saywardDecodedObjects.has(value))return value;
    __saywardDecodedObjects.add(value);
    if(Array.isArray(value)){
      for(let i=0;i<value.length;i++)value[i]=decodeDataEntities(value[i]);
    }else{
      Object.keys(value).forEach(k=>value[k]=decodeDataEntities(value[k]));
    }
    return value;
  }
  return typeof value==='string'?decodeHtmlEntities(value):value;
}
/* V5.4.44: decode strings lazily at render/TTS time; avoid full-data cold-start traversal. */
