function collectSentencePatternRanges(text,phrase){
  text=String(text||'');
  const raw=String(phrase||'').trim();
  if(!raw)return [];
  const cleaned=raw
    .replace(/\b(one's|someone's|somebody's)\b/gi,'')
    .replace(/\b(something|someone|somebody)\b/gi,'')
    .replace(/-?ing\b/gi,'')
    .replace(/[.…]+/g,' ')
    .replace(/\s+/g,' ')
    .trim();
  const tokens=cleaned.toLowerCase().match(/[a-z][a-z'-]*/g)||[];
  if(!tokens.length)return [];
  const optionalAdv=String.raw`(?:\s+(?:(?:really|very|quite|rather|so|too|just|still|already|almost|actually|definitely|usually|often|mainly|mostly|largely|completely|gradually|highly|strongly|deeply|fully|simply|quickly|slowly)|[a-z]+ly)){0,2}\s+`;
  const parts=tokens.map(t=>`(?:${highlightTokenPattern(t)})`);
  const body=parts.map((x,i)=>i?`(?:\\s+|[-–—]\\s*|${optionalAdv})${x}`:x).join('');
  const ranges=[];
  try{
    const rx=new RegExp(`\\b${body}\\b`,'gi');let m;
    while((m=rx.exec(text))){ranges.push([m.index,m.index+m[0].length]);if(!m[0].length)rx.lastIndex++;}
  }catch(e){}
  return ranges;
}
function highlightPhrase(text,phrase,cls='studyWord'){
  text=String(text||'');phrase=String(phrase||'').trim();
  if(!phrase)return escHtml(text);
  const ranges=collectHighlightRanges(text,phrase);
  if(!ranges.length)return escHtml(text);
  ranges.sort((a,b)=>a[0]-b[0]||(b[1]-b[0])-(a[1]-a[0]));
  const merged=[];
  for(const r of ranges){
    if(!merged.length||r[0]>=merged[merged.length-1][1])merged.push(r.slice());
    else if(r[1]>merged[merged.length-1][1])merged[merged.length-1][1]=r[1];
  }
  let html='',pos=0;
  for(const [a,b] of merged){html+=escHtml(text.slice(pos,a))+`<span class="${cls}">${escHtml(text.slice(a,b))}</span>`;pos=b;}
  return html+escHtml(text.slice(pos));
}

function highlightMultiplePhrases(text,phrases,cls='studyWord'){
  text=String(text||'');
  const ranges=[];
  (Array.isArray(phrases)?phrases:[phrases]).forEach(phrase=>{
    if(String(phrase||'').trim())ranges.push(...collectHighlightRanges(text,phrase));
  });
  if(!ranges.length)return escHtml(text);
  ranges.sort((a,b)=>a[0]-b[0]||(b[1]-b[0])-(a[1]-a[0]));
  const merged=[];
  for(const r of ranges){
    if(!merged.length||r[0]>merged[merged.length-1][1])merged.push(r.slice());
    else if(r[1]>merged[merged.length-1][1])merged[merged.length-1][1]=r[1];
  }
  let html='',pos=0;
  for(const [a,b] of merged){html+=escHtml(text.slice(pos,a))+`<span class="${cls}">${escHtml(text.slice(a,b))}</span>`;pos=b;}
  return html+escHtml(text.slice(pos));
}

