const AUTO={active:false,selectedDays:[],repeats:1,pass:1,token:0};
const SELECTED_PROGRESS_KEY='mv_selected_auto_progress_v1';
function studyCardId(w){return `${Number(w?.newDay||0)}::${Number(w?.newNo||0)}::${String(w?.word||'')}`}
const CARD_STUDY_KEY='mv_card_study_progress_v2';
