  if(!currentCardRepeatActive||currentCardRepeatStopRequested)return;
  currentCardRepeatStopRequested=true;
  updateCurrentRepeatButton();
  const st=document.getElementById('autoStatus');
  if(st)st.textContent=currentCardRepeatFromSelected?'현재 읽기를 끝까지 마친 뒤 전체 반복 학습으로 돌아갑니다.':'현재 읽기를 끝까지 마친 뒤 정지합니다.';
