function stopCurrentCardRepeatImmediately(){
  if(!currentCardRepeatActive&&!currentCardRepeatStopRequested)return;
  currentCardRepeatActive=false;currentCardRepeatStopRequested=false;currentCardRepeatToken++;
  try{stopSpeech()}catch(e){}
  updateCurrentRepeatButton();
}
async function startCurrentCardRepeat(){
  const w=deck?.length?cur():null;if(!w)return;
  if(currentCardRepeatActive){requestStopCurrentCardRepeat();return;}
  currentCardRepeatFromSelected=!!AUTO.active;
  currentCardRepeatStopRequested=false;
  learningPlaybackPaused=true;
  try{AUTO.token++}catch(e){}
  try{stopSpeech()}catch(e){}
  updateLearningPlaybackButton();
  currentCardRepeatActive=true;
  const token=++currentCardRepeatToken,expected=cardKey(w);
  updateCurrentRepeatButton();
  try{await acquireWakeLock()}catch(e){}
  let cycle=0;
  while(currentCardRepeatActive&&token===currentCardRepeatToken&&cardKey(cur())===expected){
    cycle++;
    const st=document.getElementById('autoStatus');
    if(st)st.textContent=`현재 단어 무한 반복 중 · ${cycle}회`;
    const ok=await autoRead(w,__renderVersion);
    if(!ok||token!==currentCardRepeatToken)break;
    if(currentCardRepeatStopRequested){
      currentCardRepeatActive=false;currentCardRepeatStopRequested=false;updateCurrentRepeatButton();
      if(currentCardRepeatFromSelected&&AUTO.active){
        const status=document.getElementById('autoStatus');if(status)status.textContent='전체 반복 학습으로 전환합니다.';
        await new Promise(r=>setTimeout(r,180));
        finishSelectedRepeatAndContinue(w);
      }else{
        learningPlaybackPaused=true;updateLearningPlaybackButton();
        const status=document.getElementById('autoStatus');if(status)status.textContent='현재 단어 읽기를 끝까지 완료하고 정지했습니다.';
      }
      return;
    }
    await new Promise(r=>setTimeout(r,220));
  }
  if(token===currentCardRepeatToken){
    currentCardRepeatActive=false;currentCardRepeatStopRequested=false;updateCurrentRepeatButton();
  }
}
const IS_KAKAO_INAPP=/KAKAOTALK/i.test(navigator.userAgent||'');
let readingScrollTimer=0;
let readingScrollSeq=0;
function clearReadingFocus(){document.querySelectorAll('.readingNow').forEach(el=>el.classList.remove('readingNow'))}
function visibleViewportHeight(){
  return Math.max(1,Math.round((window.visualViewport&&window.visualViewport.height)||window.innerHeight||document.documentElement.clientHeight||1));
}
function focusReading(el){
  clearReadingFocus();
  if(!el)return;
  el.classList.add('readingNow');
  const seq=++readingScrollSeq;
  clearTimeout(readingScrollTimer);
  readingScrollTimer=setTimeout(()=>{
    if(seq!==readingScrollSeq||!el.isConnected)return;
    try{
      const rect=el.getBoundingClientRect();
      const vh=visibleViewportHeight();
      const safeTop=IS_KAKAO_INAPP?92:76;
      const safeBottom=IS_KAKAO_INAPP?Math.max(safeTop+120,vh-118):Math.max(safeTop+120,vh-92);
      const fullySafe=rect.top>=safeTop&&rect.bottom<=safeBottom;
      if(fullySafe)return;
      if(IS_KAKAO_INAPP){
        // KakaoTalk's browser changes its visual viewport while toolbars appear/disappear.
        // Avoid stacked smooth/center scrolling and move only the minimum distance needed.
        let delta=0;
        if(rect.top<safeTop)delta=rect.top-safeTop;
        else if(rect.bottom>safeBottom)delta=rect.bottom-safeBottom;
        if(Math.abs(delta)>2)window.scrollBy({top:delta,left:0,behavior:'auto'});
      }else{
        mvPlaybackScrollTo(el,{behavior:'auto',block:'nearest'});
      }
    }catch(e){}
  },IS_KAKAO_INAPP?180:90);
}
