// ===== v7 Screen Wake Lock: independent repeat-session state =====
let __wakeLock=null;
let __repeatWakeSession=false;

function isRepeatWakeSession(){
  return __repeatWakeSession===true;
}

async function forceReleaseWakeLock(force=false){
  // 선택 DAY 연속 학습 중에는 다른 화면 로직이 실수로 release를 호출해도
  // 화면 잠금이 풀리지 않도록 보호한다. 실제 종료 시에는 먼저
  // __repeatWakeSession=false로 바뀌므로 정상적으로 해제된다.
  if(isRepeatWakeSession() && force!==true)return false;
  const lock=__wakeLock;
  __wakeLock=null;
  if(lock){
    try{await lock.release()}catch(e){}
  }
  return true;
}

async function acquireWakeLock(){
  if(!isRepeatWakeSession()){
    await forceReleaseWakeLock();
    return false;
  }
  if(!('wakeLock' in navigator) || document.visibilityState!=='visible'){
    return false;
  }
  if(__wakeLock && !__wakeLock.released)return true;

  try{
    const lock=await navigator.wakeLock.request('screen');

    // If repeat stopped while the request was pending, release immediately.
    if(!isRepeatWakeSession()){
      try{await lock.release()}catch(e){}
      return false;
    }

    __wakeLock=lock;
    lock.addEventListener('release',()=>{
      if(__wakeLock===lock)__wakeLock=null;

      // Android/browser may release the lock transiently.
      // If repeat is still running and page is visible, reacquire shortly.
      if(isRepeatWakeSession() && document.visibilityState==='visible'){
        setTimeout(()=>acquireWakeLock(),150);
      }
    });
    return true;
  }catch(e){
    __wakeLock=null;

    // Retry while repeat is still genuinely active.
    if(isRepeatWakeSession() && document.visibilityState==='visible'){
      setTimeout(()=>acquireWakeLock(),500);
    }
    return false;
  }
}

// IMPORTANT: this is called directly from the repeat-start user gesture.
function startRepeatWakeSession(){
  __repeatWakeSession=true;
  // 첫 요청은 반드시 사용자의 '선택 학습 시작' 터치 안에서 실행한다.
  acquireWakeLock();
  // 일부 Samsung/Android 브라우저는 화면 전환 직후 첫 요청을 놓칠 수 있어
  // 학습 화면이 표시된 뒤 두 번 더 확인한다.
  setTimeout(()=>{if(isRepeatWakeSession())acquireWakeLock()},250);
  setTimeout(()=>{if(isRepeatWakeSession())acquireWakeLock()},1200);
}

async function stopRepeatWakeSession(){
  __repeatWakeSession=false;
  await forceReleaseWakeLock();
}

document.addEventListener('visibilitychange',()=>{
  if(document.visibilityState==='visible' && isRepeatWakeSession()){
    acquireWakeLock();
    setTimeout(()=>{if(isRepeatWakeSession())acquireWakeLock()},300);
  }else if(!isRepeatWakeSession()){
    forceReleaseWakeLock();
  }
});
window.addEventListener('focus',()=>{if(isRepeatWakeSession())acquireWakeLock()});
window.addEventListener('pageshow',()=>{if(isRepeatWakeSession())acquireWakeLock()});

// While repeat is running, verify the lock periodically.
// Outside repeat mode, ensure no lock survives.
setInterval(()=>{
  if(isRepeatWakeSession()){
    if(!__wakeLock || __wakeLock.released) acquireWakeLock();
  }else if(__wakeLock){
    forceReleaseWakeLock();
  }
},2000);

async function autoRead(w,renderVersion=__renderVersion){
  if(isRepeatWakeSession()) await acquireWakeLock();

if(!w)return false;
  const expectedKey=cardKey(w);

  stopSpeech();
  const runSeq=TTS.seq;
  const mode=$('speechMode').value;
  if(mode==='off'){clearExactReadingFocus();return false}
  const repeatParts206=(AUTO.active&&Array.isArray(window.MV_DAY_REPEAT_PARTS_206)&&window.MV_DAY_REPEAT_PARTS_206.length)?window.MV_DAY_REPEAT_PARTS_206:null;
  const want206=(part)=>!repeatParts206||repeatParts206.includes(part);

  const ready=await waitForRenderedCard(w,renderVersion);
  if(!ready)return false;

  const alive=()=>runSeq===TTS.seq&&renderVersion===__renderVersion&&cardKey(cur())===expectedKey&&__renderedCardKey===expectedKey;
  const pause=async(ms)=>{await new Promise(r=>setTimeout(r,ms));return alive()};


  if(mode==='word'&&!repeatParts206){
    appSettings=loadAppSettings();
    const wordReadRepeat=settingInt('wordReadRepeat',3,1,10);
    for(let n=1;n<=wordReadRepeat;n++){
      if(!alive())return false;
      $('autoStatus').textContent=`단어 읽기 ${n}/${wordReadRepeat}회: ${w.word}`;
      scrollReadingTarget($('word'));
      await speakOne(w.word,.78,'en-US');
      if(!alive())return false;
      if(w.meaning){
        if(!await pause(80))return false;
        $('autoStatus').textContent=`단어 뜻 ${n}/${wordReadRepeat}회`;
        scrollReadingTarget($('meaning'),{wordMeaningGroup:true,wordEl:$('word')});
        await speakOne(w.meaning,.92,'ko-KR',$('meaning'));
        if(!alive())return false;
      }
      if(n<wordReadRepeat&&!await pause(180))return false;
    }
    clearExactReadingFocus();
    $('autoStatus').textContent=`단어 읽기 완료: 영어 단어와 한글 뜻을 ${wordReadRepeat}회 읽었습니다.`;
    return true;
  }

  // 학습 단어 + 뜻
  if(want206('word')){
    if(!alive())return false;
    $('autoStatus').textContent='읽는 중: '+w.word;
    scrollReadingTarget($('word'));
    await speakOne(w.word,.78,'en-US');
    if(!alive())return false;
    if(w.meaning){
      if(!await pause(0))return false;
      $('autoStatus').textContent='읽는 중: 단어 뜻';
      scrollReadingTarget($('meaning'),{wordMeaningGroup:true,wordEl:$('word')});
      await speakOne(w.meaning,.92,'ko-KR',$('meaning'));
      if(!alive())return false;
    }
  }

  // 첫 회화 예문: 영어
  if(want206('example')&&w.example){
    if(!await pause(0))return false;
    $('autoStatus').textContent='읽는 중: 회화 예문';
    scrollReadingTarget($('ex'));
    await speakTwice(w.example,.84);
    if(!alive())return false;
  }

  // 패러프레이즈: 영어
  if(want206('paraphrase')&&(w.paraphrase||w.example)){
    if(!await pause(20))return false;
    $('autoStatus').textContent='읽는 중: 패러프레이즈';
    scrollReadingTarget($('q'));
    for(let n=0;n<settingInt('exampleRepeat',2,1,5);n++){await speakComplete(w.paraphrase||w.example,getSpeechRate(),'en-US');if(n<settingInt('exampleRepeat',2,1,5)-1&&!await pause(120))return false;}
    if(!alive())return false;
  }

  // '단어 + 예문 + 패러프레이즈'로 저장되어 있던 기존 설정에서도
  // 학습 카드의 나머지 정보까지 빠짐없이 이어서 읽는다.

  if(want206('extra')){
    // Collocation: 등록된 모든 영어 표현
    const collocs=normalizedCollocationsOf(w).map(x=>x.en).filter(Boolean);
    if(collocs.length){
      if(!await pause(20))return false;
      $('autoStatus').textContent='읽는 중: Collocation';
      scrollReadingTarget($('collocationList'));
      for(const c of collocs){
        if(!alive())return false;
        for(let n=0;n<settingInt('collocationRepeat',1,1,3);n++){await speakComplete(decodeHtmlEntities(c),getSpeechRate(),'en-US');if(n<settingInt('collocationRepeat',1,1,3)-1&&!await pause(100))return false;}
        if(!alive())return false;
        if(!await pause(20))return false;
      }
    }

    // 유의어 / 차이점: 영어 유의어만
    const syns=w.synonyms||[];
    if(syns.length){
      if(!await pause(20))return false;
      $('autoStatus').textContent='읽는 중: 유의어';
      scrollReadingTarget($('synonymList'));
      for(const item of syns){
        if(!alive())return false;
        let en='';
        if(Array.isArray(item))en=item[0]||'';
        else if(item&&typeof item==='object')en=item.en||item.word||item.synonym||item.antonym||'';
        else en=String(item||'');
        if(en){for(let n=0;n<settingInt('synonymRepeat',1,1,3);n++){await speakComplete(decodeHtmlEntities(String(en)),getSpeechRate(),'en-US');if(n<settingInt('synonymRepeat',1,1,3)-1&&!await pause(100))return false;}}
        if(!alive())return false;
        if(!await pause(20))return false;
      }
    }else if(actualSynonymUsed(w)){
      if(!await pause(20))return false;
      $('autoStatus').textContent='읽는 중: 유의어';
      scrollReadingTarget($('synonymBadge'));
      for(let n=0;n<settingInt('synonymRepeat',1,1,3);n++){await speakComplete(actualSynonymUsed(w),getSpeechRate(),'en-US');if(n<settingInt('synonymRepeat',1,1,3)-1&&!await pause(100))return false;}
      if(!alive())return false;
    }

    // 문장에서 사용된 회화 패턴과 활용 예문도 마지막까지 읽는다.
    const usedPatternText=decodeHtmlEntities(String(w.pattern||w.used_pattern||w.collocation||w.phrase||'')).trim();
    if(usedPatternText){
      if(!await pause(40))return false;
      $('autoStatus').textContent='읽는 중: 회화 패턴';
      scrollReadingTarget($('usedPattern'));
      await speakComplete(usedPatternText,getSpeechRate(),'en-US');
      if(!alive())return false;
    }
    const pExamples=patternExamplesOf(w).map(x=>decodeHtmlEntities(String(x||''))).filter(Boolean);
    if(pExamples.length){
      if(!await pause(40))return false;
      $('autoStatus').textContent='읽는 중: 패턴 활용 예문';
      scrollReadingTarget($('usedPatternExamples'));
      for(const x of pExamples){
        if(!alive())return false;
        for(let n=0;n<settingInt('patternRepeat',1,1,3);n++){await speakComplete(x,getSpeechRate(),'en-US');if(n<settingInt('patternRepeat',1,1,3)-1&&!await pause(100))return false;}
        if(!alive())return false;
        if(!await pause(50))return false;
      }
    }

  }

  clearExactReadingFocus();
  $('autoStatus').textContent='전체 읽기 완료: 단어·뜻·예문·패러프레이즈·Collocation·유의어/반의어·회화 패턴까지 읽었습니다.';
  return true;
}
async function autoReadAndAdvance(w,renderVersion=__renderVersion){
  const autoToken=++AUTO.token;
  const expectedKey=cardKey(w);
  updateAutoBadge();

  const completed=await autoRead(w,renderVersion);
  if(!completed)return;

  // v5.3.275: integrated repeat owns navigation after a card has been fully read.
  // The legacy renderVersion/__renderedCardKey guard can change during the long
  // DAY reading sequence on Android even though the same card is still current.
  // That produced the exact symptom: status says "전체 읽기 완료" but playback stops.
  if(window.MV_ALL_REPEAT_215?.active){
    if(!AUTO.active)return;
    if(cardKey(cur())!==expectedKey)return;

    const st=stats[w.word];
    st.studyCount=(st.studyCount||0)+1;
    st.lastSeen=Date.now();
    save();
    await new Promise(r=>setTimeout(r,260));
    if(!AUTO.active||!window.MV_ALL_REPEAT_219?.active)return;

    if(i<deck.length-1){
      const next=()=>{i++;render(true);};
      if(typeof window.mvDayAutoAdvance266==='function')await window.mvDayAutoAdvance266(next);
      else next();
      return;
    }
    if(AUTO.pass<AUTO.repeats){
      const restart=()=>{AUTO.pass++;i=0;render(true);};
      if(typeof window.mvDayAutoAdvance266==='function')await window.mvDayAutoAdvance266(restart);
      else restart();
      return;
    }

    stopSpeech();
    clearSelectedProgress();
    AUTO.active=false;
    forceReleaseWakeLock();
    clearExactReadingFocus();
    updateAutoBadge();
    $('bar').style.width='100%';
    if(typeof window.MV_DAY_ONCE_COMPLETE_219==='function'){
      const done=window.MV_DAY_ONCE_COMPLETE_219;
      window.MV_DAY_ONCE_COMPLETE_219=null;
      setTimeout(()=>done('day'),80);
    }else if(window.MV_ALL_REPEAT_219?.active){
      setTimeout(()=>window.advanceAllRepeat219?.(),80);
    }else{
      setTimeout(()=>window.allRepeatAdvance215?.(),80);
    }
    return;
  }

  if(!AUTO.active||autoToken!==AUTO.token)return;
  if(renderVersion!==__renderVersion||cardKey(cur())!==expectedKey||__renderedCardKey!==expectedKey)return;

  const st=stats[w.word];st.studyCount=(st.studyCount||0)+1;st.lastSeen=Date.now();save();
  await new Promise(r=>setTimeout(r,260));

  if(!AUTO.active||autoToken!==AUTO.token)return;
  if(renderVersion!==__renderVersion||cardKey(cur())!==expectedKey||__renderedCardKey!==expectedKey)return;

  if(i<deck.length-1){
    const next=()=>{i++;render(true);};
    if(typeof window.mvDayAutoAdvance266==='function')await window.mvDayAutoAdvance266(next);
    else next();
    return;
  }
  if(AUTO.pass<AUTO.repeats){
    const restart=()=>{AUTO.pass++;i=0;render(true);};
    if(typeof window.mvDayAutoAdvance266==='function')await window.mvDayAutoAdvance266(restart);
    else restart();
    return;
  }

  stopSpeech();clearSelectedProgress();AUTO.active=false; forceReleaseWakeLock();clearExactReadingFocus();updateAutoBadge();$('bar').style.width='100%';
  if(window.MV_ALL_REPEAT_219?.active){
    if(typeof window.MV_DAY_ONCE_COMPLETE_219==='function'){
      const done=window.MV_DAY_ONCE_COMPLETE_219;
      window.MV_DAY_ONCE_COMPLETE_219=null;
      setTimeout(()=>done('day'),80);
      return;
    }
  }
  if(window.MV_ALL_REPEAT_215?.active){
    setTimeout(()=>window.allRepeatAdvance215?.(),80);
    return;
  }
  if(window.MV_ALL_REPEAT_209?.active){
    setTimeout(()=>window.allRepeatAdvance209?.(),80);
    return;
  }
  $('finishSummary').innerHTML=`선택한 ${AUTO.selectedDays.length}개 Day · ${deck.length}개 카드를 ${AUTO.repeats}회 자동 학습했습니다.`;
  $('finishOverlay').classList.remove('hidden');
}

function applyQuizReviewResult(st,isCorrect){
  if(!st)return;
  const intervals=[0,1,3,7,14,30];
  const now=Date.now();
  if(isCorrect){
    st.reviewStep=Math.min(Math.max((st.reviewStep||0)+1,1),intervals.length-1);
    st.dueAt=now+intervals[st.reviewStep]*86400000;
  }else{
    st.reviewStep=0;
    st.dueAt=now+3*3600000;
  }
}
