function todayReviewWords(){
  let now=Date.now();
  let due=W.filter(w=>{let s=stats[w.word];return (s.dueAt&&s.dueAt<=now)||(!s.dueAt&&s.quizWrong>0);});
  return due.sort((a,b)=>reviewScore(b)-reviewScore(a));
}
function dueLabelForWord(w){
  let s=stats[w.word],ts=s.dueAt||0;
  if((s.studyCount||0)===0 && !ts)return {text:'미학습',cls:'unlearned'};
  if((s.studyCount||0)>0 && !ts)return {text:'학습 중',cls:'learning'};
  let d=ts-Date.now();
  if(d<=0)return {text:'복습 필요',cls:'now'};
  let h=d/3600000;
  if(h<24)return {text:`복습 예정 · ${Math.max(1,Math.ceil(h))}시간 후`,cls:'soon'};
  let days=Math.ceil(h/24);
  return {text:`복습 예정 · ${days}일 후`,cls:'scheduled'};
}
function allScheduledWords(){
  return [...W];
}
function renderForget(){
  stopAllReadingForNavigation();
  if(!document.getElementById('forgetList'))return;
  let now=Date.now(),day=86400000;
  let all=allScheduledWords();
  let scheduled=all.filter(w=>stats[w.word].dueAt>0);
  let due=scheduled.filter(w=>stats[w.word].dueAt<=now);
  let tomorrow=scheduled.filter(w=>stats[w.word].dueAt>now&&stats[w.word].dueAt<=now+day);
  let later=scheduled.filter(w=>stats[w.word].dueAt>now+day);
  let reviewCandidates=todayReviewWords();
  $('forgetDueCount').textContent=reviewCandidates.length;
  $('forgetNow').textContent=reviewCandidates.length;
  $('forgetTomorrow').textContent=tomorrow.length;
  $('forgetLater').textContent=later.length;
  $('forgetStartBtn').disabled=false;
  $('forgetStartBtn').textContent=reviewCandidates.length?`오늘 복습 시작 (${reviewCandidates.length}개)`:'오늘 복습 시작';

  let sort=$('forgetSort')?$('forgetSort').value:'due';
  let list=[...all];
  if(sort==='due')list.sort((a,b)=>{
    let ad=stats[a.word].dueAt||Number.MAX_SAFE_INTEGER,bd=stats[b.word].dueAt||Number.MAX_SAFE_INTEGER;
    let aNow=ad<=now?0:1,bNow=bd<=now?0:1;
    return aNow-bNow || reviewScore(b)-reviewScore(a) || ad-bd;
  });
  if(sort==='weak')list.sort((a,b)=>reviewScore(b)-reviewScore(a));
  if(sort==='time')list.sort((a,b)=>(stats[a.word].dueAt||Number.MAX_SAFE_INTEGER)-(stats[b.word].dueAt||Number.MAX_SAFE_INTEGER));

  $('forgetList').innerHTML=list.length?list.map(w=>{
    let s=stats[w.word],d=dueLabelForWord(w);
    return `<div class="forgetItem">
      <div class="forgetItemTop">
        <div><div class="forgetWord">${w.word}</div><div class="forgetMeaning">${w.meaning}</div></div>
        <span class="forgetDue ${d.cls}">${d.text}</span>
      </div>
      <div class="forgetMeta">학습 ${s.studyCount}회 · 퀴즈 정답 ${s.quizCorrect||0}회 · 퀴즈 오답 ${s.quizWrong||0}회 · 복습 단계 ${s.reviewStep||0}</div>
    </div>`;
  }).join(''):'아직 망각곡선에 등록된 단어가 없습니다. 먼저 학습을 시작해 보세요.';
}

let reviewSession={
  mode:'standard', words:[], recallQueue:[], recallIndex:0, recallAttempts:{}, recallMissWords:[],
  quizWords:[], quizIndex:0, quizWrongWords:[], quizCorrect:0, productionWords:[], productionIndex:0, maxRecallAttempts:2
};

function openReviewModeChooser(){
  let a=todayReviewWords();
  if(!a.length){
    $('reviewModeOverlay').classList.remove('hidden');
    document.querySelector('.reviewModeBox h2').textContent='오늘 복습할 단어가 없습니다 🎉';
    document.querySelector('.reviewModeBox p').textContent='현재 복습 시점이 된 단어가 없습니다. 학습이나 퀴즈를 진행하면 망각곡선에 자동으로 등록됩니다.';
    document.querySelectorAll('.reviewModeBtn').forEach(b=>b.classList.add('hidden'));
    return;
  }
  document.querySelector('.reviewModeBox h2').textContent='오늘 복습 방식';
  document.querySelector('.reviewModeBox p').textContent=`오늘 복습할 ${a.length}개 단어를 어떤 깊이로 복습할지 선택하세요.`;
  document.querySelectorAll('.reviewModeBtn').forEach(b=>b.classList.remove('hidden'));
  $('reviewModeOverlay').classList.remove('hidden');
}
function closeReviewModeChooser(){$('reviewModeOverlay').classList.add('hidden')}

function beginReviewSession(mode){
  let a=todayReviewWords();
  let limit=parseInt($('forgetLimit').value,10)||10;
  if(limit<999)a=a.slice(0,limit);
  if(!a.length)return;
  reviewSession={mode,words:a,recallQueue:[...a],recallIndex:0,recallAttempts:{},recallMissWords:[],quizWords:[],quizIndex:0,quizWrongWords:[],quizCorrect:0,productionWords:[],productionIndex:0,maxRecallAttempts:mode==='fast'?1:(mode==='standard'?2:3)};
  closeReviewModeChooser();
  $('reviewSessionOverlay').classList.remove('hidden');
  $('reviewFlowPreview').textContent=mode==='fast'?'⚡ Recall 1회 → 완료':mode==='standard'?'⭐ Recall 최대 2회 → 틀린 단어 4지선다 → 완료':'🎤 Recall 최대 3회 → 영↔한 양방향 퀴즈 → 회화 패턴 확인 → 완료';
  $('recallPanel').classList.remove('hidden');$('reviewQuizPanel').classList.add('hidden');$('productionPanel').classList.add('hidden');$('reviewDonePanel').classList.add('hidden');
  showRecallItem();
}

function updateReviewProgress(idx,total){
  $('reviewSessionIdx').textContent=Math.min(idx+1,total);$('reviewSessionTotal').textContent=total;
  $('reviewSessionBar').style.width=total?((idx+1)/total*100)+'%':'0%';
}

function showRecallItem(){
  if(reviewSession.recallIndex>=reviewSession.recallQueue.length){finishRecallStage();return;}
  let w=reviewSession.recallQueue[reviewSession.recallIndex];
  $('reviewStageLabel').textContent='RECALL';
  let modeTitle=reviewSession.mode==='fast'?'⚡ 빠른 확인':(reviewSession.mode==='standard'?'⭐ 표준 Recall':'🎤 심화 Recall');
  $('reviewSessionTitle').innerHTML=`${modeTitle} <span class="reviewModeBadge ${reviewSession.mode}">${reviewSession.mode==='fast'?'1회전':reviewSession.mode==='standard'?'최대 2회':'최대 3회'}</span>`;
  updateReviewProgress(reviewSession.recallIndex,reviewSession.recallQueue.length);
  $('recallWord').textContent=w.word;$('recallMeaning').textContent=w.meaning;$('recallMeaning').classList.add('hidden');
  $('showRecallMeaning').classList.remove('hidden');$('showRecallMeaning').textContent='뜻 보기';
  speechSynthesis.cancel();speakOne(w.word,.78);
}
function currentRecall(){return reviewSession.recallQueue[reviewSession.recallIndex]}
function markRecall(knownIt){
  let w=currentRecall(),key=w.word;
  reviewSession.recallAttempts[key]=(reviewSession.recallAttempts[key]||0)+1;
  let st=stats[key];
  if(knownIt){
    st.studyCount+=1;st.streak+=1;
    if(st.streak>=3){st.miss=Math.max(0,st.miss-1);st.streak=0}
    if(!known.includes(key))known.push(key);
  }else{
    st.studyCount+=1;st.miss+=1;st.streak=0;st.lastMiss=Date.now();known=known.filter(x=>x!==key);
    if(!reviewSession.recallMissWords.some(x=>x.word===key))reviewSession.recallMissWords.push(w);
    if(reviewSession.recallAttempts[key]<reviewSession.maxRecallAttempts)reviewSession.recallQueue.push(w);
  }
  save();reviewSession.recallIndex++;showRecallItem();
}
function finishRecallStage(){
  if(reviewSession.mode==='fast'){finishReviewSession();return;}
  if(reviewSession.mode==='standard'){
    reviewSession.quizWords=reviewSession.recallMissWords.map((w,n)=>({wordObj:w,direction:n%2===0?'enKo':'koEn'}));
  }else{
    reviewSession.quizWords=[];
    reviewSession.recallMissWords.forEach(w=>{
      reviewSession.quizWords.push({wordObj:w,direction:'enKo'});
      reviewSession.quizWords.push({wordObj:w,direction:'koEn'});
    });
  }
  if(!reviewSession.quizWords.length){finishReviewSession();return;}
  reviewSession.quizIndex=0;
  $('recallPanel').classList.add('hidden');$('reviewQuizPanel').classList.remove('hidden');
  showReviewQuiz();
}

function showReviewQuiz(){
  if(reviewSession.quizIndex>=reviewSession.quizWords.length){finishReviewQuizStage();return;}
  let item=reviewSession.quizWords[reviewSession.quizIndex],q=item.wordObj||item,direction=item.direction||'enKo';
  $('reviewStageLabel').textContent=reviewSession.mode==='complete'?'QUIZ · 양방향':'QUIZ';
  $('reviewSessionTitle').innerHTML=`${direction==='enKo'?'영어 → 한글':'한글 → 영어'} <span class="reviewModeBadge ${reviewSession.mode}">${reviewSession.mode==='complete'?'2방향':'1문제'}</span>`;
  updateReviewProgress(reviewSession.quizIndex,reviewSession.quizWords.length);
  $('reviewQuizFeedback').className='reviewQuizFeedback hidden';$('reviewQuizNext').classList.add('hidden');
  let choices=[q,...W.filter(x=>x.word!==q.word).sort(()=>Math.random()-.5).slice(0,3)].sort(()=>Math.random()-.5);
  $('reviewQuizPrompt').textContent=direction==='enKo'?q.word:q.meaning;
  $('reviewQuizOptions').innerHTML=choices.map(x=>`<button class="reviewQuizOption" data-word="${x.word}">${direction==='enKo'?x.meaning:x.word}</button>`).join('');
  if(direction==='enKo'){speechSynthesis.cancel();speakOne(q.word,.78)}
  let answered=false;
  document.querySelectorAll('.reviewQuizOption').forEach(btn=>btn.onclick=()=>{
    if(answered)return;answered=true;
    let correct=btn.dataset.word===q.word,st=stats[q.word];
    document.querySelectorAll('.reviewQuizOption').forEach(b=>{b.disabled=true;if(b.dataset.word===q.word)b.classList.add('correct')});
    if(correct){
      reviewSession.quizCorrect++;st.quizCorrect+=1;st.quizStreak=(st.quizStreak||0)+1;applyQuizReviewResult(st,true);
      $('reviewQuizFeedback').className='reviewQuizFeedback ok';$('reviewQuizFeedback').textContent='맞았습니다!';
      speechSynthesis.cancel();(async()=>{await speakOne(q.word,.78);await new Promise(r=>setTimeout(r,220));await speakOne(q.example,.84)})();
    }else{
      btn.classList.add('wrong');st.quizWrong+=1;st.quizStreak=0;st.lastQuizWrong=Date.now();applyQuizReviewResult(st,false);
      if(!reviewSession.quizWrongWords.some(x=>x.word===q.word))reviewSession.quizWrongWords.push(q);
      $('reviewQuizFeedback').className='reviewQuizFeedback no';$('reviewQuizFeedback').innerHTML=`틀렸습니다. 정답은 <b>${q.word}</b> 입니다.`;
      speechSynthesis.cancel();speakOne(q.word,.78);
    }
    save();$('reviewQuizNext').classList.remove('hidden');
  });
}
function finishReviewQuizStage(){
  if(reviewSession.mode!=='complete'){finishReviewSession();return;}
  let combined=[...reviewSession.recallMissWords];
  reviewSession.quizWrongWords.forEach(w=>{if(!combined.some(x=>x.word===w.word))combined.push(w)});
  reviewSession.productionWords=combined;
  if(!combined.length){finishReviewSession();return;}
  reviewSession.productionIndex=0;
  $('reviewQuizPanel').classList.add('hidden');$('productionPanel').classList.remove('hidden');
  showProductionItem();
}
function showProductionItem(){
  if(reviewSession.productionIndex>=reviewSession.productionWords.length){finishReviewSession();return;}
  let w=reviewSession.productionWords[reviewSession.productionIndex];
  $('reviewStageLabel').textContent='PRODUCTION · COMPLETE';$('reviewSessionTitle').innerHTML='직접 말해보기 <span class="reviewModeBadge complete">완전 복습 전용</span>';
  updateReviewProgress(reviewSession.productionIndex,reviewSession.productionWords.length);
  $('productionWord').textContent=w.word;$('productionMeaning').textContent=w.meaning;
  $('productionQuestion').innerHTML=highlightPhrase(w.paraphrase||w.example,w.synonymUsed||'','synonymWord');$('productionQuestionKo').textContent=w.paraphraseTranslation||w.translation||'';
  const pattern=String(w.pattern||w.used_pattern||w.collocation||w.phrase||'').trim();
  $('productionPattern').textContent=pattern||'등록된 추가 회화 패턴이 없습니다.';
  $('productionPattern').classList.toggle('patternEmpty',!pattern);
  $('productionPatternMeaning').textContent=String(w.pattern_ko_recommended||w.patternMeaning||w.pattern_ko||'').trim();
  $('productionPatternMeaning').style.display=$('productionPatternMeaning').textContent?'block':'none';
  const examples=patternExamplesOf(w);
  $('productionPatternExamples').innerHTML=examples.map(x=>'<div class="patternExampleItem">'+highlightPhrase(x,pattern,'patternWord')+'</div>').join('');
  $('productionPatternExamples').style.display=examples.length?'flex':'none';
}
function finishReviewSession(){
  // 복습 예정일은 Recall 버튼이 아니라 실제 퀴즈 정답·오답에서만 변경됩니다.
  save();
  $('recallPanel').classList.add('hidden');$('reviewQuizPanel').classList.add('hidden');$('productionPanel').classList.add('hidden');$('reviewDonePanel').classList.remove('hidden');
  $('reviewStageLabel').textContent='DONE';$('reviewSessionTitle').textContent='복습 완료';
  $('reviewSessionIdx').textContent=reviewSession.words.length;$('reviewSessionTotal').textContent=reviewSession.words.length;$('reviewSessionBar').style.width='100%';
  let miss=reviewSession.recallMissWords.length,qw=reviewSession.quizWrongWords.length;
  let modeName={fast:'빠른 복습',standard:'표준 복습',complete:'완전 복습'}[reviewSession.mode];
  let detail=reviewSession.mode==='fast'
    ?'1회 Recall만 진행했습니다.'
    :reviewSession.mode==='standard'
      ?'최대 2회 Recall + 어려운 단어 1회 퀴즈를 진행했습니다.'
      :'최대 3회 Recall + 영어↔한글 양방향 퀴즈 + 회화 패턴 확인을 진행했습니다.';
  $('reviewDoneSummary').innerHTML=`<b>${modeName}</b> ${reviewSession.words.length}개 완료<br>${detail}<br><br>Recall에서 어려웠던 단어 <b>${miss}개</b>${reviewSession.mode!=='fast'?`<br>퀴즈 오답 <b>${qw}개</b>`:''}<br><br>퀴즈 오답 단어는 약 3시간 후, 정답 단어는 1·3·7·14·30일 간격으로 다시 나옵니다.`;
}
function closeReviewSession(){
  speechSynthesis.cancel();$('reviewSessionOverlay').classList.add('hidden');renderForget();
}

function startForgettingReview(){openReviewModeChooser()}


document.querySelectorAll('.reviewModeBtn').forEach(b=>b.onclick=()=>beginReviewSession(b.dataset.mode));
$('closeReviewMode').onclick=closeReviewModeChooser;
$('reviewSessionExit').onclick=closeReviewSession;
$('reviewDoneClose').onclick=closeReviewSession;
$('showRecallMeaning').onclick=()=>{$('recallMeaning').classList.remove('hidden');$('showRecallMeaning').classList.add('hidden')};
$('recallKnow').onclick=()=>markRecall(true);
$('recallMiss').onclick=()=>markRecall(false);
$('recallSpeak').onclick=()=>{speechSynthesis.cancel();speakOne(currentRecall().word,.78)};
$('reviewQuizNext').onclick=()=>{reviewSession.quizIndex++;showReviewQuiz()};
$('productionHearQ').onclick=()=>{let w=reviewSession.productionWords[reviewSession.productionIndex];stopSpeech();speakOne(w.paraphrase||w.example,.84)};
$('productionPatternSpeak').onclick=async()=>{let w=reviewSession.productionWords[reviewSession.productionIndex];stopSpeech();const examples=patternExamplesOf(w);if(examples.length){for(const x of examples)await speakOne(x,.84)}else await speakOne(w.pattern||w.used_pattern||w.collocation||w.phrase||'',.82)};
$('productionNext').onclick=()=>{reviewSession.productionIndex++;showProductionItem()};

$('orderMode').value=localStorage.getItem(packKey('order'))||'quizWrongDesc';
const savedSpeechMode=localStorage.getItem(packKey('speech'));
$('speechMode').value=(savedSpeechMode==='off'||savedSpeechMode==='word'||savedSpeechMode==='full'||savedSpeechMode==='all')?savedSpeechMode:'full';
