function quizPool(){
  const base=quizAllWrongMode
    ? ALL_WORDS.filter(w=>(stats[w.word]?.quizWrong||0)>0)
    : ALL_WORDS.filter(w=>Number(w.newDay)===Number(quizSelectedDay));
  return applyQuizFilter(base);
}

function buildQuizDeck(){
  const pool=quizPool();
  const lexicalEligible=pool.filter(w=>fallbackSynonymsOf(w).length||antonymsOf(w).length);
  if(quizMode==='sentence'){
    quizAllWrongMode=false;
    let sentencePool=sentenceSourceMode==='practice'
      ? practiceSentenceCardsMinimal([quizSelectedDay])
      : ALL_WORDS.filter(w=>Number(w.newDay)===Number(quizSelectedDay));
    sentencePool.forEach(q=>ensureSentenceStats(q));
    if(quizFilterMode==='wrong'){
      sentencePool=sentencePool.filter(isWeakSentence).sort((a,b)=>{
        const sa=ensureSentenceStats(a),sb=ensureSentenceStats(b);
        return (sb.sentenceWrong||0)-(sa.sentenceWrong||0)||(sb.lastSentenceWrong||0)-(sa.lastSentenceWrong||0)||(Number(a.newNo)||0)-(Number(b.newNo)||0);
      });
    }else{
      sentencePool=sentencePool.sort((a,b)=>(Number(a.newDay)||0)-(Number(b.newDay)||0)||(Number(a.newNo)||0)-(Number(b.newNo)||0)||(Number(a.originalNo)||0)-(Number(b.originalNo)||0));
    }
    quizDeck=sentencePool;
  }else{
    quizDeck = quizMode==='lexical' ? shuffleDeck(lexicalEligible) : shuffleDeck(pool);
  }
  quizIndex = 0;
  quizSessionDone = false;
  quizSessionWrong = [];
  updateQuizFilterCount();
}

