function sentenceRecordingTime(sec){
  sec=Math.max(0,Math.round(Number(sec)||0));
  return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;
}
function sentenceRecordingAvailable(){
  return !!(window.MediaRecorder&&navigator.mediaDevices&&navigator.mediaDevices.getUserMedia);
}
function sentenceRecordingMime(){
  if(!window.MediaRecorder)return '';
  const types=['audio/mpeg','audio/mp3','audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg;codecs=opus'];
  return types.find(t=>{try{return MediaRecorder.isTypeSupported(t)}catch(e){return false}})||'';
}


async function sentenceRecordingPrepareMic(){
  if(sentenceRecordingPreparedStream && sentenceRecordingPreparedStream.active){
    return sentenceRecordingPreparedStream;
  }
  if(sentenceRecordingPreparePromise){
    return sentenceRecordingPreparePromise;
  }
  if(!sentenceRecordingAvailable()){
    throw new Error('MIC_UNSUPPORTED');
  }

  sentenceRecordingPreparePromise=(async()=>{
    try{
      const stream=await navigator.mediaDevices.getUserMedia({
        audio:{
          echoCancellation:true,
          noiseSuppression:true,
          autoGainControl:true
        }
      });
      sentenceRecordingPreparedStream=stream;
      sentenceRecordingPreparedAt=Date.now();
      return stream;
    }finally{
      sentenceRecordingPreparePromise=null;
    }
  })();

  return sentenceRecordingPreparePromise;
}

function sentenceRecordingReleasePreparedMic(){
  if(sentenceRecordingPreparedStream){
    try{
      sentenceRecordingPreparedStream.getTracks().forEach(t=>t.stop());
    }catch(e){}
    sentenceRecordingPreparedStream=null;
  }
  sentenceRecordingPreparedAt=0;
}

let mvMicWarmDeniedShown272=false;
function sentenceRecordingWarmMic(){
  // 3단계 진입 시 마이크를 미리 준비한다.
  // 이미 권한이 있으면 버튼 누르기 전에 스트림이 준비되어 거의 즉시 녹음 가능.
  if(!sentenceRecordingAvailable())return;
  sentenceRecordingPrepareMic().catch(e=>{
    if(e&&e.name==='NotAllowedError'&&!mvMicWarmDeniedShown272){
      mvMicWarmDeniedShown272=true;
      sentenceRecordingToast('마이크 권한 필요 · 설정 → 앱 → Chrome → 권한 → 마이크 → 앱 사용 중에만 허용');
    }
  });
}

function sentenceRecordingStopWave(){
  if(sentenceRecordingWaveRAF){cancelAnimationFrame(sentenceRecordingWaveRAF);sentenceRecordingWaveRAF=null;}
  try{if(sentenceRecordingSourceNode)sentenceRecordingSourceNode.disconnect();}catch(e){}
  sentenceRecordingSourceNode=null;
  sentenceRecordingAnalyser=null;
  if(sentenceRecordingAudioCtx){
    try{sentenceRecordingAudioCtx.close();}catch(e){}
    sentenceRecordingAudioCtx=null;
  }
}
function sentenceRecordingStartWave(stream){
  try{
    const AC=window.AudioContext||window.webkitAudioContext;
    if(!AC)return;

    sentenceRecordingAudioCtx=new AC();
    sentenceRecordingAnalyser=sentenceRecordingAudioCtx.createAnalyser();
    sentenceRecordingAnalyser.fftSize=1024;
    sentenceRecordingAnalyser.smoothingTimeConstant=.88;
    sentenceRecordingSourceNode=sentenceRecordingAudioCtx.createMediaStreamSource(stream);
    sentenceRecordingSourceNode.connect(sentenceRecordingAnalyser);

    const data=new Uint8Array(sentenceRecordingAnalyser.fftSize);
    let displayedLevel=0;
    let lastSampleAt=0;

    const draw=now=>{
      if(!sentenceRecordingAnalyser)return;
      sentenceRecordingAnalyser.getByteTimeDomainData(data);

      let sum=0;
      for(let i=0;i<data.length;i++){
        const v=(data[i]-128)/128;
        sum+=v*v;
      }

      const rms=Math.sqrt(sum/data.length);

      // Light noise gate so the line stays calm between words.
      const noiseFloor=.017;
      let voice=Math.max(0,rms-noiseFloor);
      voice=Math.min(1,voice*9.4);

      // Fast attack, slower release for a recorder-like envelope.
      const attack=.36;
      const release=.11;
      displayedLevel += (voice-displayedLevel) * (voice>displayedLevel?attack:release);

      // Keep one envelope sample roughly every 65ms.
      if(!lastSampleAt || now-lastSampleAt>=65){
        let sample=displayedLevel;
        if(sample<.045)sample=0;
        sentenceRecordingWaveHistory.push(sample);

        // Safety cap only; about 5 minutes at ~65ms/sample.
        if(sentenceRecordingWaveHistory.length>4800){
          sentenceRecordingWaveHistory.shift();
        }
        lastSampleAt=now;
      }

      sentenceRecordingDrawWaveform({
        canvasId:'sentenceWaveCanvas',
        history:sentenceRecordingWaveHistory,
        mode:'recording'
      });

      sentenceRecordingWaveRAF=requestAnimationFrame(draw);
    };

    sentenceRecordingWaveRAF=requestAnimationFrame(draw);
  }catch(e){}
}
function sentenceRecordingDrawWaveform({
  canvasId,
  history,
  mode='ready',
  progress=0
}){
  const canvas=document.getElementById(canvasId);
  if(!canvas)return;

  const rect=canvas.getBoundingClientRect();
  const dpr=Math.min(2,window.devicePixelRatio||1);
  const w=Math.max(1,Math.floor(rect.width*dpr));
  const h=Math.max(1,Math.floor(rect.height*dpr));
  if(canvas.width!==w||canvas.height!==h){
    canvas.width=w;
    canvas.height=h;
  }

  const ctx=canvas.getContext('2d');
  ctx.clearRect(0,0,w,h);

  const mid=h/2;
  const cursorX=w/2;
  const step=4.0*dpr;
  const barW=1.55*dpr;
  const maxAmp=h*.39;
  const minAmp=.9*dpr;
  const count=history.length;

  // Subtle baseline.
  ctx.strokeStyle='rgba(148,163,184,.26)';
  ctx.lineWidth=1*dpr;
  ctx.setLineDash([2*dpr,4*dpr]);
  ctx.beginPath();
  ctx.moveTo(6*dpr,mid);
  ctx.lineTo(w-6*dpr,mid);
  ctx.stroke();
  ctx.setLineDash([]);

  if(count>0){
    let currentIndex=0;

    if(mode==='recording'){
      currentIndex=count-1;
    }else if(mode==='playback' || mode==='paused' || mode==='complete'){
      currentIndex=Math.max(0,Math.min(count-1,progress*(count-1)));
    }

    // Only draw samples that could be visible around the fixed center cursor.
    const visibleEachSide=Math.ceil((w/2)/step)+4;
    const first=Math.max(0,Math.floor(currentIndex-visibleEachSide));
    const last=Math.min(count-1,Math.ceil(currentIndex+visibleEachSide));

    for(let i=first;i<=last;i++){
      const v=history[i]||0;
      const prev=history[Math.max(0,i-1)]||0;
      const next=history[Math.min(count-1,i+1)]||0;
      const smooth=v*.58+prev*.21+next*.21;

      const amp=smooth<=0
        ? minAmp
        : Math.max(minAmp,Math.pow(smooth,.72)*maxAmp);

      const x=cursorX+(i-currentIndex)*step;
      if(x<-barW || x>w+barW)continue;

      const y=mid-amp;

      let fill='rgba(203,213,225,.72)';

      if(mode==='recording'){
        // Past speech is red/pink, future space is empty.
        fill = i<=currentIndex
          ? 'rgba(244,63,94,.82)'
          : 'rgba(203,213,225,.45)';
      }else{
        // Playback: already-played audio is purple, upcoming audio is gray.
        fill = i<=currentIndex
          ? 'rgba(91,79,244,.92)'
          : 'rgba(203,213,225,.82)';
      }

      ctx.fillStyle=fill;
      ctx.beginPath();
      if(ctx.roundRect){
        ctx.roundRect(x,y,barW,amp*2,barW/2);
      }else{
        ctx.rect(x,y,barW,amp*2);
      }
      ctx.fill();
    }
  }

  // Fixed center playback/record cursor.
  ctx.strokeStyle='#ef4444';
  ctx.lineWidth=1.45*dpr;
  ctx.beginPath();
  ctx.moveTo(cursorX,7*dpr);
  ctx.lineTo(cursorX,h-7*dpr);
  ctx.stroke();
}
function sentenceRecordingStopPlaybackAnimation(){
  if(sentenceRecordingPlaybackRAF){
    cancelAnimationFrame(sentenceRecordingPlaybackRAF);
    sentenceRecordingPlaybackRAF=null;
  }
}

function sentenceRecordingAnimatePlayback(){
  sentenceRecordingStopPlaybackAnimation();

  const audio=document.getElementById('sentenceMyAudio');
  if(!audio)return;

  const tick=()=>{
    const duration=(audio.duration&&isFinite(audio.duration)&&audio.duration>0)
      ? audio.duration
      : sentenceRecordingDuration||0;

    const progress=duration>0
      ? Math.max(0,Math.min(1,(audio.currentTime||0)/duration))
      : 0;

    sentenceRecordingDrawWaveform({
      canvasId:'sentenceWaveCanvas',
      history:sentenceRecordingWaveHistory,
      mode:audio.paused?'paused':'playback',
      progress
    });

    const big=document.getElementById('sentenceRecordingBigTime');
    if(big){
      const cur=sentenceRecordingTime(audio.currentTime||0);
      const total=sentenceRecordingTime(duration);
      big.textContent=`${cur} / ${total}`;
    }

    if(!audio.paused && !audio.ended){
      sentenceRecordingPlaybackRAF=requestAnimationFrame(tick);
    }
  };

  tick();
}
function sentenceRecordingStopTracks(){
  sentenceRecordingStopWave();
  if(sentenceRecordingTimer){clearInterval(sentenceRecordingTimer);sentenceRecordingTimer=null;}
  // 준비된 마이크 스트림은 유지해서 재녹음을 즉시 시작할 수 있게 한다.
  if(sentenceRecordingStream && sentenceRecordingStream!==sentenceRecordingPreparedStream){
    sentenceRecordingStream.getTracks().forEach(t=>{try{t.stop()}catch(e){}});
  }
  sentenceRecordingStream=null;
}
function sentenceRecordingReset(){
  if(sentenceRecordingRecorder&&sentenceRecordingRecorder.state==='recording'){
    try{sentenceRecordingRecorder.stop()}catch(e){}
  }
  sentenceRecordingStopTracks();
  sentenceRecordingRecorder=null;
  sentenceRecordingChunks=[];
  sentenceRecordingBlob=null;
  sentenceRecordingQuestion=null;
  sentenceRecordingCapturedAt=0;
  sentenceRecordingDuration=0;
  sentenceRecordingWaveHistory=[];
  sentenceRecordingStopPlaybackAnimation();
  if(sentenceRecordingUrl){URL.revokeObjectURL(sentenceRecordingUrl);sentenceRecordingUrl='';}
}

