function sentenceRecordingPad2(v){return String(Math.max(0,Number(v)||0)).padStart(2,'0')}
function sentenceRecordingTimestamp(ms=Date.now()){
  const d=new Date(Number(ms)||Date.now());
  return `${String(d.getFullYear()).slice(-2)}${sentenceRecordingPad2(d.getMonth()+1)}${sentenceRecordingPad2(d.getDate())}_${sentenceRecordingPad2(d.getHours())}${sentenceRecordingPad2(d.getMinutes())}${sentenceRecordingPad2(d.getSeconds())}`;
}
function sentenceRecordingSanitizeName(text,maxLen=34){
  let out=String(text||'')
    .replace(/\.mp3$/i,'')
    .replace(/[\\/:*?"<>|\u0000-\u001f]/g,' ')
    .replace(/\s+/g,'_')
    .replace(/_+/g,'_')
    .replace(/^[._\s]+|[._\s]+$/g,'');
  if(!out)out='녹음';
  if(out.length>maxLen)out=out.slice(0,maxLen).replace(/_+$/,'');
  return out||'녹음';
}
function sentenceRecordingLessonTitle(q){
  if(!q||voiceRecorderIsFreeContext(q))return '음성';
  const day=Math.max(1,Number(q.newDay)||1);
  try{
    if(q.isOpicSentence && typeof STUDY_COURSES!=='undefined' && STUDY_COURSES.opic){
      const meta=STUDY_COURSES.opic.meta?.()||{};
      return meta[day]?.shortTitle||meta[day]?.title||`OPIC_${day}`;
    }
    if(q.isMyClassSentence && typeof MY_CLASS_META!=='undefined'){
      return MY_CLASS_META[day]?.title||`수업_${day}`;
    }
    if(q.isStudyCourseSentence && typeof studyCourseConfig==='function'){
      const course=q.studyCourse||'sori';
      const cfg=studyCourseConfig(course)||{};
      const meta=typeof cfg.meta==='function'?(cfg.meta()||{}):{};
      return meta[day]?.shortTitle||meta[day]?.title||`${cfg.title||course}_${day}`;
    }
  }catch(e){}
  return q.word||`수업_${day}`;
}
function sentenceRecordingDefaultFilename(q){
  const stamp=sentenceRecordingTimestamp(sentenceRecordingCapturedAt||Date.now());
  if(voiceRecorderIsFreeContext(q))return `음성_${stamp}`;
  const title=sentenceRecordingSanitizeName(sentenceRecordingLessonTitle(q),28);
  const no=sentenceRecordingPad2(q?.newNo||1);
  return `${title}_${no}_${stamp}`;
}
