  try{input.focus({preventScroll:false});input.setSelectionRange(0,input.value.length)}catch(e){try{input.focus();input.select()}catch(_){} }
  requestAnimationFrame(()=>{try{input.focus();input.setSelectionRange(0,input.value.length)}catch(e){}});
