function sentenceRecordingLoadMp3Encoder(){
  if(window.lamejs&&window.lamejs.Mp3Encoder)return Promise.resolve(window.lamejs);
  if(sentenceRecordingMp3Loader)return sentenceRecordingMp3Loader;
  const urls=[
    'https://cdn.jsdelivr.net/npm/lamejs@1.2.1/lame.min.js',
    'https://unpkg.com/lamejs@1.2.1/lame.min.js'
  ];
  sentenceRecordingMp3Loader=new Promise((resolve,reject)=>{
    let i=0;
    const next=()=>{
      if(window.lamejs&&window.lamejs.Mp3Encoder){resolve(window.lamejs);return}
      if(i>=urls.length){sentenceRecordingMp3Loader=null;reject(new Error('MP3_ENCODER_LOAD_FAILED'));return}
      const src=urls[i++];
      const script=document.createElement('script');
      script.src=src;script.async=true;script.crossOrigin='anonymous';
      script.onload=()=>{if(window.lamejs&&window.lamejs.Mp3Encoder)resolve(window.lamejs);else next()};
      script.onerror=()=>{try{script.remove()}catch(e){};next()};
      document.head.appendChild(script);
    };
    next();
  });
  return sentenceRecordingMp3Loader;
}
function sentenceRecordingFloatToInt16(audioBuffer){
  const channels=Math.max(1,audioBuffer.numberOfChannels||1);
  const len=audioBuffer.length||0;
  const out=new Int16Array(len);
  const data=[];
  for(let c=0;c<channels;c++)data.push(audioBuffer.getChannelData(c));
  for(let i=0;i<len;i++){
    let sum=0;
    for(let c=0;c<channels;c++)sum+=data[c][i]||0;
    let v=sum/channels;
    v=Math.max(-1,Math.min(1,v));
    out[i]=v<0?v*0x8000:v*0x7fff;
  }
  return out;
}
async function sentenceRecordingToMp3(blob){
  if(!blob)throw new Error('NO_RECORDING');
  if(/^audio\/(mpeg|mp3)$/i.test(String(blob.type||'')))return blob;
  const lame=await sentenceRecordingLoadMp3Encoder();
  const AC=window.AudioContext||window.webkitAudioContext;
  if(!AC)throw new Error('AUDIO_CONTEXT_UNSUPPORTED');
  const ctx=new AC();
  let audioBuffer;
  try{
    const arr=await blob.arrayBuffer();
    audioBuffer=await ctx.decodeAudioData(arr.slice(0));
  }finally{
    try{await ctx.close()}catch(e){}
  }
  const sampleRate=Math.round(audioBuffer.sampleRate||48000);
  const pcm=sentenceRecordingFloatToInt16(audioBuffer);
  const encoder=new lame.Mp3Encoder(1,sampleRate,128);
  const chunks=[];
  const block=1152;
  for(let i=0;i<pcm.length;i+=block){
    const part=pcm.subarray(i,Math.min(i+block,pcm.length));
    const encoded=encoder.encodeBuffer(part);
    if(encoded&&encoded.length)chunks.push(new Int8Array(encoded));
  }
  const flushed=encoder.flush();
  if(flushed&&flushed.length)chunks.push(new Int8Array(flushed));
  if(!chunks.length)throw new Error('MP3_ENCODING_EMPTY');
  return new Blob(chunks,{type:'audio/mpeg'});
}
function sentenceRecordingDownloadBlob(blob,filename){
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=filename;a.style.display='none';
  document.body.appendChild(a);
  a.click();
  setTimeout(()=>{try{a.remove()}catch(e){};try{URL.revokeObjectURL(url)}catch(e){}},1600);
}

// ===== V5.3.285 · Download/my_voca_record best-effort folder writer =====
// Browser security does not allow a web page to silently create arbitrary folders.
// On browsers that expose showDirectoryPicker(), the user grants Download-folder access once;
// MY VOCA then creates/reuses the my_voca_record child folder. Other browsers fall back to normal download.
const SENTENCE_RECORDING_FOLDER_NAME='my_voca_record';
const SENTENCE_RECORDING_FS_DB='my_voca_record_fs_v1';
const SENTENCE_RECORDING_FS_STORE='handles';
const SENTENCE_RECORDING_FS_KEY='downloadsParent';
let sentenceRecordingFolderHandleMemory=null;

function sentenceRecordingIsIOS(){
  const ua=String(navigator.userAgent||'');
  return /iPad|iPhone|iPod/.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
}
function sentenceRecordingFolderApiAvailable(){
  return !!(window.isSecureContext&&typeof window.showDirectoryPicker==='function');
}
function sentenceRecordingOpenFsDb(){
  return new Promise((resolve,reject)=>{
    if(!window.indexedDB){reject(new Error('INDEXEDDB_UNAVAILABLE'));return}
    const req=indexedDB.open(SENTENCE_RECORDING_FS_DB,1);
    req.onupgradeneeded=()=>{
      const db=req.result;
      if(!db.objectStoreNames.contains(SENTENCE_RECORDING_FS_STORE))db.createObjectStore(SENTENCE_RECORDING_FS_STORE);
    };
    req.onsuccess=()=>resolve(req.result);
    req.onerror=()=>reject(req.error||new Error('INDEXEDDB_OPEN_FAILED'));
  });
}
async function sentenceRecordingLoadStoredFolderHandle(){
  if(sentenceRecordingFolderHandleMemory)return sentenceRecordingFolderHandleMemory;
  try{
    const db=await sentenceRecordingOpenFsDb();
    const handle=await new Promise((resolve,reject)=>{
      const tx=db.transaction(SENTENCE_RECORDING_FS_STORE,'readonly');
      const req=tx.objectStore(SENTENCE_RECORDING_FS_STORE).get(SENTENCE_RECORDING_FS_KEY);
      req.onsuccess=()=>resolve(req.result||null);
      req.onerror=()=>reject(req.error||new Error('INDEXEDDB_READ_FAILED'));
    });
    try{db.close()}catch(e){}
    if(handle)sentenceRecordingFolderHandleMemory=handle;
    return handle||null;
  }catch(e){return null}
}
async function sentenceRecordingStoreFolderHandle(handle){
  sentenceRecordingFolderHandleMemory=handle||null;
  if(!handle)return;
  try{
    const db=await sentenceRecordingOpenFsDb();
    await new Promise((resolve,reject)=>{
      const tx=db.transaction(SENTENCE_RECORDING_FS_STORE,'readwrite');
      tx.objectStore(SENTENCE_RECORDING_FS_STORE).put(handle,SENTENCE_RECORDING_FS_KEY);
      tx.oncomplete=()=>resolve();
      tx.onerror=()=>reject(tx.error||new Error('INDEXEDDB_WRITE_FAILED'));
      tx.onabort=()=>reject(tx.error||new Error('INDEXEDDB_WRITE_ABORTED'));
    });
    try{db.close()}catch(e){}
  }catch(e){}
}
async function sentenceRecordingEnsureDownloadsParentHandle(){
  if(!sentenceRecordingFolderApiAvailable())return null;
  let handle=await sentenceRecordingLoadStoredFolderHandle();
  if(handle){
    try{
      let perm=await handle.queryPermission?.({mode:'readwrite'});
      if(perm!=='granted')perm=await handle.requestPermission?.({mode:'readwrite'});
      if(perm==='granted')return handle;
    }catch(e){}
    handle=null;
  }
  // Must run from the user's Save tap because browsers require transient user activation.
  try{
    handle=await window.showDirectoryPicker({id:'my-voca-record-downloads',mode:'readwrite',startIn:'downloads'});
    if(handle)await sentenceRecordingStoreFolderHandle(handle);
    return handle||null;
  }catch(e){
    if(e?.name==='AbortError')throw new Error('FOLDER_PICKER_CANCELLED');
    throw e;
  }
}
async function sentenceRecordingWriteToRecordFolder(parentHandle,blob,filename){
  if(!parentHandle)throw new Error('NO_FOLDER_HANDLE');
  const dir=await parentHandle.getDirectoryHandle(SENTENCE_RECORDING_FOLDER_NAME,{create:true});
  const file=await dir.getFileHandle(filename,{create:true});
  const writable=await file.createWritable();
  try{await writable.write(blob)}finally{await writable.close()}
}
async function sentenceRecordingPrepareSaveTarget(){
  if(!sentenceRecordingFolderApiAvailable())return {mode:'download',parent:null};
  const parent=await sentenceRecordingEnsureDownloadsParentHandle();
  return parent?{mode:'folder',parent}:{mode:'download',parent:null};
}
function sentenceRecordingRefreshSaveLocation(){
  const el=document.getElementById('recordingSaveLocation');
  if(!el)return;
  if(sentenceRecordingFolderApiAvailable()){
    el.textContent='📁 저장 위치: Download / my_voca_record · 첫 저장 시 Download 폴더 접근 허용';
  }else if(sentenceRecordingIsIOS()){
    el.textContent='📁 iPhone/iPad: Safari 기본 다운로드 · my_voca_record 자동 생성은 지원되지 않음';
  }else{
    el.textContent='📁 저장 위치: 브라우저 기본 다운로드 · 폴더 자동 생성 미지원 환경';
  }
}
async function sentenceRecordingConfirmSave(){
  const root=document.getElementById('recordingSaveBackdrop');
  if(!root||root.classList.contains('hidden'))return;
  const input=root.querySelector('#recordingSaveFilename');
  const save=root.querySelector('#recordingSaveConfirm');
  const status=root.querySelector('#recordingSaveStatus');
  const clean=sentenceRecordingSanitizeName(input?.value||'',80);
  if(input)input.value=clean;
  if(!sentenceRecordingBlob){sentenceRecordingToast('저장할 녹음이 없습니다.');return}
  if(save){save.disabled=true;save.textContent='MP3 변환 중…'}
  if(status)status.textContent='MP3 파일을 만들고 있습니다.';
  try{
    // Folder permission/picker must be requested immediately from this Save tap, before MP3 encoding awaits.
    if(status)status.textContent=sentenceRecordingFolderApiAvailable()?'저장 폴더를 확인하고 있습니다.':'MP3 파일을 만들고 있습니다.';
    const target=await sentenceRecordingPrepareSaveTarget();
    if(status)status.textContent='MP3 파일을 만들고 있습니다.';
    const mp3=await sentenceRecordingToMp3(sentenceRecordingBlob);
    const filename=`${clean}.mp3`;
    if(target.mode==='folder'&&target.parent){
      if(status)status.textContent='Download / my_voca_record에 저장하고 있습니다.';
      await sentenceRecordingWriteToRecordFolder(target.parent,mp3,filename);
      sentenceRecordingCloseSaveDialog();
      sentenceRecordingToast(`✅ my_voca_record / ${filename} 저장 완료`);
    }else{
      sentenceRecordingDownloadBlob(mp3,filename);
      sentenceRecordingCloseSaveDialog();
      if(sentenceRecordingIsIOS())sentenceRecordingToast(`✅ ${filename} 다운로드 시작 · iPhone에서는 Files 앱에서 폴더를 이동해 주세요.`);
      else sentenceRecordingToast(`✅ ${filename} 기본 다운로드 폴더에 저장을 시작했습니다.`);
    }
  }catch(e){
    if(save){save.disabled=false;save.textContent='다시 시도'}
    const msg=String(e?.message||e);
    if(msg.includes('FOLDER_PICKER_CANCELLED')){
      if(status)status.textContent='폴더 선택이 취소되었습니다.';
      sentenceRecordingToast('Download 폴더를 선택하면 my_voca_record 폴더를 만들어 저장합니다.');
    }else if(msg.includes('MP3_ENCODER')){
      if(status)status.textContent='MP3 변환에 실패했습니다.';
      sentenceRecordingToast('MP3 변환 모듈을 불러오지 못했습니다. 인터넷 연결을 확인한 뒤 다시 저장해 주세요.');
    }else{
      if(status)status.textContent='파일 저장에 실패했습니다.';
      sentenceRecordingToast('MP3 파일을 저장할 수 없습니다. 저장 권한 또는 브라우저 설정을 확인해 주세요.');
    }
  }
}
function sentenceRecordingToggleMine(){
  const audio=document.getElementById('sentenceMyAudio');
  if(!audio||!sentenceRecordingUrl){sentenceRecordingToast('먼저 음성을 녹음해 주세요.');return}
  if(audio.paused){audio.play().catch(()=>{})}else{audio.pause()}
}
function sentenceRecordingFileActionsMarkup(q){
  const has=!!sentenceRecordingUrl;
  return `<div class="sentenceRecorderFileActions" aria-label="녹음 파일 기능">
    <button id="sentenceActionPlayBtn" class="sentenceRecorderFileAction" type="button" ${has?'':'disabled'}>▶ 내 녹음 듣기</button>
    <button id="sentenceActionSaveBtn" class="sentenceRecorderFileAction sentenceRecorderMp3Action" type="button" ${has?'':'disabled'}>⬇ MP3 파일 저장</button>
  </div>`;
}

function sentenceRecordingMarkup(q=null){
  const recording=!!(sentenceRecordingRecorder&&sentenceRecordingRecorder.state==='recording');
  const has=!!sentenceRecordingUrl;
  const isFree=voiceRecorderIsFreeContext(q);

  const stateLabel = recording ? '녹음 중' : (has ? '녹음 완료' : '눌러서 말하기');
  const stateClass = recording ? 'recording' : (has ? 'complete' : 'ready');

  const total = sentenceRecordingTime(sentenceRecordingDuration||0);

  return `<div class="sentenceRecorderUnified ${stateClass}">
    <div class="sentenceRecorderStateRow">
      <div class="sentenceRecorderState">
        <span class="sentenceRecorderDot"></span>
        <b>${stateLabel}</b>
      </div>
    </div>

    <div id="sentenceRecordingBigTime" class="sentenceRecorderTime">
      ${recording ? '0:00.0' : (has ? total : '0:00.0')}
    </div>
    <div class="sentenceRecorderMode">기본 모드</div>

    <canvas id="sentenceWaveCanvas" class="sentenceRecorderWave" aria-label="음성 파형"></canvas>

    <div class="sentenceRecorderControls">
      <button type="button" class="sentenceRecorderSideBtn" id="sentenceBookmarkBtn" aria-label="북마크">
        <span class="sentenceRecorderIcon">🔖</span>
        <small>북마크</small>
      </button>

      ${
        recording
          ? `<button id="sentenceRecordBtn" class="sentenceRecorderMainBtn stop" type="button" aria-label="녹음 종료">■</button>`
          : has
            ? `<button id="sentenceMyPlay" class="sentenceRecorderMainBtn play" type="button" aria-label="내 녹음 재생">▶</button>`
            : `<button id="sentenceRecordBtn" class="sentenceRecorderMainBtn record" type="button" aria-label="녹음 시작">🎙</button>`
      }

      ${
        has
          ? `<button id="sentenceRerecordBtn" class="sentenceRecorderSideBtn" type="button" aria-label="다시 녹음">
               <span class="sentenceRecorderIcon">↻</span>
               <small>다시 녹음</small>
             </button>`
          : `<button class="sentenceRecorderSideBtn sentenceRecorderSideBtnMuted" type="button" aria-label="완료" disabled>
               <span class="sentenceRecorderIcon">■</span>
               <small>완료</small>
             </button>`
      }
    </div>

    <div class="sentenceRecorderHint">
      ${
        recording
          ? '말을 하고 가운데 버튼을 누르면 녹음이 완료됩니다.'
          : has
            ? '재생 버튼을 눌러 내 목소리를 들어보세요.'
            : '빨간색 버튼을 누르면 바로 녹음이 시작됩니다.'
      }
    </div>

    ${has ? `<audio id="sentenceMyAudio" preload="metadata" src="${sentenceRecordingUrl}"></audio>` : ''}
    ${isFree?'':sentenceRecordingFileActionsMarkup(q)}
  </div>`;
}
function sentenceCompareMarkup(){
  return `<div class="sentenceCompareBox">
    <div class="sentenceCompareTitle">💡 들어보고 비교해 보세요</div>
    <div class="sentenceCompareButtons">
      <button id="sentenceCompareMine" type="button" ${sentenceRecordingUrl?'':'disabled'}>▶ 내 녹음</button>
      <button id="sentenceCompareAnswer" type="button">🔊 정답 듣기</button>
    </div>
    <div class="sentenceCompareTip">내 녹음 → 정답 → 내 녹음 순서로 들어보세요.</div>
  </div>`;
}
async function sentenceRecordingStart(q){
  if(!sentenceRecordingAvailable()){
    sentenceRecordingToast('이 브라우저에서는 음성 녹음을 지원하지 않습니다.');
    return;
  }

  try{
    if(sentenceRecordingQuestion&&sentenceRecordingQuestion!==q)sentenceRecordingReset();

    // 버튼 반응은 즉시: 먼저 UI를 녹음 상태로 바꾼다.
    sentenceRecordingQuestion=q;
    sentenceRecordingStartedAt=Date.now();
    sentenceRecordingCapturedAt=sentenceRecordingStartedAt;

    const stream=await sentenceRecordingPrepareMic();
    sentenceRecordingStream=stream;

    const mime=sentenceRecordingMime();
    const rec=mime?new MediaRecorder(stream,{mimeType:mime}):new MediaRecorder(stream);

    sentenceRecordingChunks=[];
    sentenceRecordingWaveHistory=[];
    sentenceRecordingRecorder=rec;

    rec.ondataavailable=e=>{
      if(e.data&&e.data.size)sentenceRecordingChunks.push(e.data);
    };

    rec.onerror=()=>{
      sentenceRecordingStopTracks();
      sentenceRecordingRecorder=null;
      sentenceRecordingToast('녹음 중 오류가 발생했습니다.');
    };

    rec.onstop=()=>{
      sentenceRecordingDuration=(Date.now()-sentenceRecordingStartedAt)/1000;
      if(sentenceRecordingUrl)URL.revokeObjectURL(sentenceRecordingUrl);

      sentenceRecordingBlob=new Blob(
        sentenceRecordingChunks,
        {type:rec.mimeType||mime||'audio/webm'}
      );

      // 브라우저 메모리 재생 + 필요 시 MP3 변환 저장
      sentenceRecordingUrl=URL.createObjectURL(sentenceRecordingBlob);

      sentenceRecordingStopTracks();
      sentenceRecordingRecorder=null;

      voiceRecorderRenderContext(q);
    };

    // timeslice를 작게 해서 시작 반응을 빠르게.
    rec.start(80);

    // recorder가 실제 recording 상태에 들어간 직후 공용 UI 갱신
    voiceRecorderRenderContext(q);

    // 파형 즉시 시작
    sentenceRecordingStartWave(stream);

    sentenceRecordingTimer=setInterval(()=>{
      const elapsed=(Date.now()-sentenceRecordingStartedAt)/1000;
      const el=document.getElementById('sentenceRecordingClock');
      const big=document.getElementById('sentenceRecordingBigTime');
      if(el)el.textContent='● 녹음 중';
      if(big){
        const min=Math.floor(elapsed/60);
        const sec=Math.floor(elapsed%60);
        const tenth=Math.floor((elapsed-Math.floor(elapsed))*10);
        big.textContent=`${min}:${String(sec).padStart(2,'0')}.${tenth}`;
      }
    },100);

  }catch(e){
    sentenceRecordingStopTracks();
    sentenceRecordingRecorder=null;

    if(e&&e.name==='NotAllowedError'){
      sentenceRecordingToast('마이크 권한이 꺼져 있습니다. 휴대폰 설정 → 앱 → Chrome → 권한 → 마이크 → 앱 사용 중에만 허용로 변경한 뒤 다시 눌러 주세요.');
    }else if(location.protocol==='content:' || !window.isSecureContext){
      sentenceRecordingToast('현재 파일(content://)에서는 마이크 사용이 제한될 수 있습니다. 먼저 Chrome 마이크 권한을 허용하고, 계속 안 되면 앱을 HTTPS 주소에서 실행해 주세요.');
    }else{
      sentenceRecordingToast('마이크를 시작할 수 없습니다. 휴대폰 설정 → 앱 → Chrome → 권한 → 마이크를 확인한 뒤 다시 시도해 주세요.');
    }
  }
}
function sentenceRecordingStop(){
  if(sentenceRecordingRecorder&&sentenceRecordingRecorder.state==='recording'){
    try{sentenceRecordingRecorder.stop()}catch(e){}
  }
}

function sentenceCompareEnsure(q){
  if(document.getElementById('sentenceCompareMine'))return;
  if(!sentenceRecordingUrl)return;
  const box=document.querySelector('.sentenceRecallBox');
  if(!box)return;
  if(document.getElementById('sentenceCompareMine'))return;

  const actions=box.querySelector('.sentenceStageActions');
  if(actions){
    actions.insertAdjacentHTML('beforebegin',sentenceCompareMarkup());
  }else{
    box.insertAdjacentHTML('beforeend',sentenceCompareMarkup());
  }

  const mine=$('sentenceCompareMine');
  if(mine)mine.onclick=()=>{
    const a=$('sentenceMyAudio');
    if(a){a.currentTime=0;a.play().catch(()=>{});}
  };

  const answer=$('sentenceCompareAnswer');
  if(answer)answer.onclick=()=>voiceRecorderSpeakReference(q).then(()=>{
    if(!voiceRecorderIsFreeContext(q)&&quizMode==='sentence'&&quizCurrent===q&&sentenceRecallStage===3)sentenceIncrementCount(q);
  });
}

function sentenceRecordingBind(q){
  sentenceRecordingWarmMic();

  // 3단계 진입 직후부터 녹음기 UI와 빈 파형을 바로 표시
  if(!sentenceRecordingRecorder && !sentenceRecordingUrl){
    sentenceRecordingDrawWaveform({
      canvasId:'sentenceWaveCanvas',
      history:[],
      mode:'ready',
      progress:0
    });
  }

  const recordBtn=$('sentenceRecordBtn');
  if(recordBtn){
    recordBtn.onclick=()=>{
      if(sentenceRecordingRecorder&&sentenceRecordingRecorder.state==='recording'){
        sentenceRecordingStop();
      }else{
        sentenceRecordingStart(q);
      }
    };
  }

  const rerecord=$('sentenceRerecordBtn');
  if(rerecord){
    rerecord.onclick=()=>{
      sentenceRecordingReset();
      voiceRecorderRenderContext(q);
      setTimeout(()=>sentenceRecordingStart(q),40);
    };
  }

  const done=$('sentenceRecordDoneBtn');
  if(done){
    done.onclick=()=>{
      if(sentenceRecordingRecorder&&sentenceRecordingRecorder.state==='recording'){
        sentenceRecordingStop();
      }
    };
  }

  const audio=$('sentenceMyAudio');
  const play=$('sentenceMyPlay');
  const actionPlay=$('sentenceActionPlayBtn');
  const actionSave=$('sentenceActionSaveBtn');
  if(actionPlay)actionPlay.onclick=()=>sentenceRecordingToggleMine();
  if(actionSave)actionSave.onclick=()=>sentenceRecordingOpenSaveDialog(q);

  if(audio&&play){
    // show the saved waveform immediately
    sentenceRecordingDrawWaveform({
      canvasId:'sentenceWaveCanvas',
      history:sentenceRecordingWaveHistory,
      mode:'complete',
      progress:0
    });

    play.onclick=()=>{
      if(audio.paused){
        audio.play().catch(()=>{});
      }else{
        audio.pause();
      }
    };

    audio.onplay=()=>{
      play.textContent='Ⅱ';
      play.classList.add('playing');
      sentenceRecordingAnimatePlayback();
    };

    audio.onpause=()=>{
      play.textContent='▶';
      play.classList.remove('playing');
      sentenceRecordingStopPlaybackAnimation();
      sentenceRecordingAnimatePlayback();
    };

    audio.onended=()=>{
      play.textContent='▶';
      play.classList.remove('playing');
      sentenceRecordingStopPlaybackAnimation();
      sentenceRecordingDrawWaveform({
        canvasId:'sentenceWaveCanvas',
        history:sentenceRecordingWaveHistory,
        mode:'complete',
        progress:1
      });
      const big=$('sentenceRecordingBigTime');
      if(big)big.textContent=`${sentenceRecordingTime(sentenceRecordingDuration)} / ${sentenceRecordingTime(sentenceRecordingDuration)}`;
    };

    audio.onloadedmetadata=()=>{
      if(isFinite(audio.duration)&&audio.duration>0){
        sentenceRecordingDuration=audio.duration;
      }
      const big=$('sentenceRecordingBigTime');
      if(big)big.textContent=sentenceRecordingTime(sentenceRecordingDuration);
      sentenceRecordingDrawWaveform({
        canvasId:'sentenceWaveCanvas',
        history:sentenceRecordingWaveHistory,
        mode:'complete',
        progress:0
      });
    };
  }

  const compareMine=$('sentenceCompareMine');
  if(compareMine){
    compareMine.onclick=()=>{
      const a=$('sentenceMyAudio');
      const main=$('sentenceMyPlay');
      if(a){
        a.currentTime=0;
        a.play().catch(()=>{});
        if(main){
          main.textContent='Ⅱ';
          main.classList.add('playing');
        }
        sentenceRecordingAnimatePlayback();
      }
    };
  }

  const compareAnswer=$('sentenceCompareAnswer');
  if(compareAnswer){
    compareAnswer.onclick=()=>voiceRecorderSpeakReference(q).then(()=>{
      if(!voiceRecorderIsFreeContext(q)&&quizMode==='sentence'&&quizCurrent===q&&sentenceRecallStage===3)sentenceIncrementCount(q);
    });
  }
}

function renderSentenceStage(q,stage,visible=false){
  if(!q||quizMode!=='sentence')return;
  clearSentenceRecallTimer();
  sentenceRecallStage=stage;
  sentenceRecallVisible=visible;
  sentenceSaveResume();
  const full=sentenceHighlightedHtml(q);
  const ko=q?.isPracticeSentence?highlightKoreanPracticeText(q):recallEscape(sentenceKo(q));
  const variantLabel=sentenceVariantLabel();
  const isPara=sentenceRecallVariant==='paraphrase';
  const stagePattern=sentencePattern(q);
  const stagePatternKo=sentencePatternMeaning(q);
  let patternInfo='';
  if(q?.isPracticeSentence){
    const basePatterns=Array.isArray(q.practicePatterns)?q.practicePatterns.filter(Boolean):[];
    const baseMeanings=Array.isArray(q.practicePatternMeanings)?q.practicePatternMeanings:[];
    const extraPatterns=Array.isArray(q.practiceExtraPatterns)?q.practiceExtraPatterns.filter(Boolean):[];
    const extraMeanings=Array.isArray(q.practiceExtraPatternMeanings)?q.practiceExtraPatternMeanings:[];
    if(basePatterns.length||extraPatterns.length){
      const baseRows=basePatterns.map((pat,i)=>`<div class="sentencePatternPair compact"><span class="patternText">${recallEscape(pat)}</span>${baseMeanings[i]?`<span class="patternKo">${recallEscape(baseMeanings[i])}</span>`:''}</div>`).join('');
      const extraRows=extraPatterns.map((pat,i)=>`<div class="sentencePatternPair compact"><span class="patternText extra">${recallEscape(pat)}</span>${extraMeanings[i]?`<span class="patternKo">${recallEscape(extraMeanings[i])}</span>`:''}</div>`).join('');
      patternInfo=`<div class="sentencePatternInfo sentencePatternUnified"><div class="sentencePatternUnifiedTitle">문장에서 사용된 핵심 회화 패턴</div><div class="sentencePatternLegend">${basePatterns.length?'<span class="legendBase">● 학습 패턴</span>':''}${extraPatterns.length?'<span class="legendExtra">● 추가 패턴</span>':''}</div>${baseRows}${extraRows}</div>`;
    }
  }
  let content='';
  let actions='';
  if(stage===1){
    content=`<div class="sentenceEnglish">${full}</div>${patternInfo}`;
    actions=`<div class="sentenceStageActions one"><button id="sentenceToStage2" class="sentenceStageBtn sentencePrimary" type="button">2단계 · 빈칸 문장 말하기</button></div>`;
  }else if(stage===2){
    content=`<div id="sentencePracticeText" class="sentenceEnglish">${visible?full:sentenceMaskedHtml(q)}</div>${patternInfo}`;
    actions=`<div class="sentenceStage2Actions"><button id="sentenceStage2Repeat" class="sentenceStageBtn sentenceRepeatBtn ${sentenceStage2Repeat?'active':''}" type="button">🔁 반복 듣기 ${sentenceStage2Repeat?'ON':'OFF'}</button><button id="sentenceToStage3" class="sentenceStageBtn sentencePrimary" type="button">③ 전체 문장 말하기</button></div><div class="sentenceStage2Aux"><button id="sentenceToggle" class="sentenceStageBtn sentenceSecondary" type="button">${visible?'문장 숨기기':'👁 문장 보기'}</button></div>`;
  }else{
    content=sentenceRecordingMarkup(q)+(visible?`<div id="sentencePracticeText" class="sentenceEnglish">${full}</div>`:`<div id="sentencePracticeText" class="sentenceHiddenBox">영어 문장을 보지 않고 전체 문장을 말해 보세요.</div>`);
    if(!isPara && hasParaphraseSentence(q)){
      actions=`<div class="sentenceStageActions"><button id="sentenceToggle" class="sentenceStageBtn sentenceSecondary" type="button">${visible?'문장 숨기기':'문장 보기 · 듣기'}</button><button id="sentenceListen" class="sentenceStageBtn sentenceSecondary" type="button">🔊 문장 다시 듣기</button><button id="sentenceToParaphrase" class="sentenceStageBtn sentencePrimary" type="button">다음 · 패러프레이징 연습</button></div>`;
    }else{
      actions=`<div class="sentenceStageActions"><button id="sentenceToggle" class="sentenceStageBtn sentenceSecondary" type="button">${visible?'문장 숨기기':'문장 보기 · 듣기'}</button><button id="sentenceCorrect" class="sentenceStageBtn sentenceSuccess" type="button">맞았어요</button><button id="sentenceWrong" class="sentenceStageBtn sentenceDanger" type="button">오답</button><button id="sentenceListen" class="sentenceStageBtn sentenceSecondary" type="button">🔊 문장 다시 듣기</button></div>`;
    }
  }
  const instruction=stage===1?'문장을 계속 들으면서 자연스럽게 따라 말하세요.':stage===2?(isPara?'핵심 표현과 학습 단어를 가렸습니다. 빈칸을 직접 말해 보세요.':'핵심 단어·표현을 우선 포함해 문장의 50% 이상을 가렸습니다. 보이는 부분을 단서로 전체 문장을 말해 보세요.'):'한글 뜻만 보고 영어 문장을 처음부터 끝까지 말해 보세요.';
  const stageNav=`<div class="sentenceStageNav" aria-label="문장 말하기 단계 이동">
    <button type="button" class="sentenceStageNavBtn ${stage===1?'active':''}" data-sentence-stage="1">① 듣고 따라하기</button>
    <span class="sentenceStageNavArrow">→</span>
    <button type="button" class="sentenceStageNavBtn ${stage===2?'active':''}" data-sentence-stage="2">② 빈칸 말하기</button>
    <span class="sentenceStageNavArrow">→</span>
    <button type="button" class="sentenceStageNavBtn ${stage===3?'active':''}" data-sentence-stage="3">③ 한글 보고 말하기</button>
  </div>`;
  $('opts').innerHTML=`<div class="sentenceRecallBox">${stageNav}<div id="sentencePracticeCount" class="sentencePracticeCount"></div><div class="sentencePromptKo">${ko}</div>${content}${instruction?`<div class="sentenceInstruction">${instruction}</div>`:''}${actions}</div>`;
  sentenceUpdateCountDisplay(q);
  document.querySelectorAll('[data-sentence-stage]').forEach(btn=>{
    btn.onclick=()=>{
      const target=Number(btn.dataset.sentenceStage||stage);
      stopSentenceRepeat(true);
      if(target!==2)sentenceStage2Repeat=false;
      if(target===2&&stage!==2)sentenceStage2Repeat=false;
      renderSentenceStage(q,target,false);
    };
  });
  $('quizMeta').textContent=`${quizScopeLabel()} · 문장 말하기 · Day 순서 · ${variantLabel} ${stage}단계 · ${quizIndex+1}/${quizDeck.length}`;
  if(stage===1){
    $('sentenceToStage2').onclick=()=>{
      stopSentenceRepeat(true);
      sentenceStage2Repeat=false;
      renderSentenceStage(q,2,false);
    };
    startSentenceContinuousRepeat(q,1);
  }else if(stage===2){
    $('sentenceToggle').onclick=()=>{
      const next=!sentenceRecallVisible;
      sentenceRecallVisible=next;
      const textEl=$('sentencePracticeText');
      if(textEl)textEl.innerHTML=next?full:sentenceMaskedHtml(q);
      const toggleBtn=$('sentenceToggle');
      if(toggleBtn)toggleBtn.textContent=next?'문장 숨기기':'👁 문장 보기';
    };
    $('sentenceStage2Repeat').onclick=()=>{
      sentenceStage2Repeat=!sentenceStage2Repeat;
      stopSentenceRepeat(true);
      renderSentenceStage(q,2,sentenceRecallVisible);
      if(sentenceStage2Repeat)startSentenceContinuousRepeat(q,2);
    };
    $('sentenceToStage3').onclick=()=>{
      sentenceStage2Repeat=false;
      stopSentenceRepeat(true);
      renderSentenceStage(q,3,false);
    };
  }else{
    sentenceRecordingBind(q);
    $('sentenceToggle').onclick=()=>{
      const next=!sentenceRecallVisible;
      renderSentenceStage(q,3,next);
      if(next)speakSentenceOnce(q).then(()=>{if(quizMode==='sentence'&&quizCurrent===q&&sentenceRecallStage===3)sentenceIncrementCount(q)});
    };
    $('sentenceListen').onclick=()=>speakSentenceOnce(q).then(()=>{if(quizMode==='sentence'&&quizCurrent===q&&sentenceRecallStage===3)sentenceIncrementCount(q)});
    const paraBtn=$('sentenceToParaphrase');
    if(paraBtn)paraBtn.onclick=()=>{
      stopSpeech();
      sentenceRecallVariant='paraphrase';
      sentenceRecallStage=0;
      sentenceRecallVisible=false;
      sentenceSaveResume();
      $('opts').innerHTML=`<div class="sentenceRecallBox"><div class="sentenceStageBadge">패러프레이징 문장 · 준비</div><div class="sentencePromptKo">${recallEscape(sentenceKo(q,'paraphrase'))}</div><div id="sentenceCountdown" class="sentenceCountdown">${settingInt('recallDelay',3,1,10)}</div><div class="sentenceInstruction">설정한 시간 동안 같은 뜻의 패러프레이징 영어 문장을 먼저 말해 보세요.</div></div>`;
      $('quizMeta').textContent=`${quizScopeLabel()} · Day 순서 · 패러프레이징 문장을 떠올리세요 · ${quizIndex+1}/${quizDeck.length}`;
      let count=settingInt('recallDelay',3,1,10);
      const tick=()=>{
        if(quizMode!=='sentence'||quizCurrent!==q||sentenceRecallVariant!=='paraphrase')return;
        count--;
        const el=$('sentenceCountdown');if(el)el.textContent=String(Math.max(count,0));
        if(count<=0){sentenceRecallTimer=null;renderSentenceStage(q,1,true);}
        else sentenceRecallTimer=setTimeout(tick,1000);
      };
      sentenceRecallTimer=setTimeout(tick,1000);
    };
    const correctBtn=$('sentenceCorrect');if(correctBtn)correctBtn.onclick=()=>recordRecallResult(q,true);
    const wrongBtn=$('sentenceWrong');if(wrongBtn)wrongBtn.onclick=()=>recordRecallResult(q,false);
  }
}

function newSentenceRecallQuestion(){
  clearSentenceRecallTimer();
  if(!quizDeck.length)buildQuizDeck();
  if(!quizDeck.length){
    $('qw').textContent='완료 🎉';$('quizMeta').textContent=quizScopeLabel()+' 조건에 해당하는 문장이 없습니다.';$('opts').innerHTML='';$('quizFeedback').className='quizFeedback hidden';$('nextq').textContent='다시하기';$('nextq').classList.remove('hidden');quizSessionDone=true;return;
  }
  if(quizIndex>=quizDeck.length){showQuizFinish();return;}
  sentenceRecordingReset();
  quizAnswered=false;
  quizCurrent=quizDeck[quizIndex];

  const resume=(arguments.length&&arguments[0]&&typeof arguments[0]==='object')?arguments[0]:null;
  sentenceRecallStage=resume?Math.max(1,Math.min(3,Number(resume.stage)||1)):1;
  sentenceRecallVisible=resume?!!resume.visible:true;
  sentenceRecallVariant=resume?.variant==='paraphrase'?'paraphrase':'original';

  const q=quizCurrent;updateQuizProgress();updateQuestionNavButtons();updateQuizStats(q);
  $('quiz').classList.add('ko-en-mode');
  $('qw').textContent=sentenceSourceMode==='practice'?`실전 문장 ${quizIndex+1}`:sentenceKo(q);
  $('quizMeta').textContent=`${quizScopeLabel()} · Day 등록 순서 · ${quizIndex+1}/${quizDeck.length}`;
  $('quizFeedback').className='quizFeedback hidden';$('quizFeedback').textContent='';$('nextq').classList.remove('hidden');
  renderSentenceStage(q,sentenceRecallStage,sentenceRecallVisible);
  sentenceSaveResume();
}


function sentenceRestartCurrentContext(){
  sentenceClearResume();
  quizIndex=0;
  sentenceRecallStage=1;
  sentenceRecallVisible=true;
  sentenceRecallVariant='original';
  buildQuizDeck();
  newq();
}
window.sentenceRestartCurrentContext=sentenceRestartCurrentContext;

function updateQuestionNavButtons(){
  const prev=$('prevq'),next=$('nextq');
  if(prev)prev.disabled=quizSessionDone ? quizDeck.length===0 : quizIndex<=0;
  if(next && !quizSessionDone){
    next.textContent='다음 →';
  }
}

let favoriteSelectorWords=[];
function syncFavoriteSelectorHome(){
  const overall=document.getElementById('overallFavorite');if(overall)overall.textContent=favs.length;
  try{renderDayGrid();}catch(e){}
}
function setFavoriteWord(word,on){
  if(on){if(!favs.includes(word))favs.push(word);}else{favs=favs.filter(x=>x!==word);}
  save();syncFavoriteSelectorHome();updateLearningFavoriteButton();
}
function renderFavoriteSelector(){
  clearQuizAutoNext();clearSentenceRecallTimer();stopSentenceRepeat(true);stopSpeech();
  quizSessionDone=false;quizAnswered=false;
  favoriteSelectorWords=applyQuizFilter(ALL_WORDS.filter(w=>Number(w.newDay)===Number(quizSelectedDay))).sort((a,b)=>(Number(a.newNo)||0)-(Number(b.newNo)||0)||(Number(a.originalNo)||0)-(Number(b.originalNo)||0));
  const selected=favoriteSelectorWords.filter(w=>favs.includes(w.word)).length;
  $('qw').textContent=`${dayDisplayLabel(quizSelectedDay)} 전체 단어`;
  $('quizMeta').textContent=favoriteSelectorWords.length?`${favoriteSelectorWords.length}개를 훑어보고 모르는 단어를 선택하세요.`:`${quizFilterLabel()} 조건에 해당하는 단어가 없습니다.`;
  $('idx').textContent=selected;$('total').textContent=favoriteSelectorWords.length;$('bar').style.width=favoriteSelectorWords.length?(selected/favoriteSelectorWords.length*100)+'%':'0%';
  $('quizFeedback').className='quizFeedback hidden';$('quizFeedback').textContent='';
  const rows=favoriteSelectorWords.map((w,idx)=>{
    const on=favs.includes(w.word);
    return `<label class="favoriteWordRow ${on?'selected':''}" data-fav-index="${idx}"><input class="favoriteWordCheck" type="checkbox" ${on?'checked':''}><span class="favoriteWordMain"><b>${escHtml(w.word)}</b><span>${escHtml(w.meaning||'')}</span></span><span class="favoriteWordStar">${on?'★':'☆'}</span></label>`;
  }).join('');
  $('opts').innerHTML=`<div class="favoritePickerSummary"><span>모르는 모르는 단어 선택</span><span id="favoritePickerCount">${selected}/${favoriteSelectorWords.length}</span></div><div class="favoritePickerToolbar"><button id="favoriteSelectAll" type="button">전체 선택</button><button id="favoriteClearAll" type="button">전체 해제</button><button id="favoriteSelectUnlearned" type="button">미학습만 선택</button></div><div class="favoriteWordList">${rows}</div><button id="favoritePickerDone" class="favoritePickerDone" type="button">${unknownSelectorReturnDay?'선택 완료 · 학습 시작':'선택 완료 · 홈으로'}</button>`;
  const refresh=()=>{
    const count=favoriteSelectorWords.filter(w=>favs.includes(w.word)).length;
    const c=$('favoritePickerCount');if(c)c.textContent=`${count}/${favoriteSelectorWords.length}`;
    $('idx').textContent=count;$('bar').style.width=favoriteSelectorWords.length?(count/favoriteSelectorWords.length*100)+'%':'0%';
  };
  document.querySelectorAll('.favoriteWordRow').forEach(row=>{
    const idx=Number(row.dataset.favIndex),w=favoriteSelectorWords[idx],box=row.querySelector('input'),star=row.querySelector('.favoriteWordStar');
    box.onchange=()=>{setFavoriteWord(w.word,box.checked);row.classList.toggle('selected',box.checked);star.textContent=box.checked?'★':'☆';refresh();};
  });
  $('favoriteSelectAll').onclick=()=>{favoriteSelectorWords.forEach(w=>setFavoriteWord(w.word,true));renderFavoriteSelector();};
  $('favoriteClearAll').onclick=()=>{favoriteSelectorWords.forEach(w=>setFavoriteWord(w.word,false));renderFavoriteSelector();};
  $('favoriteSelectUnlearned').onclick=()=>{favoriteSelectorWords.forEach(w=>setFavoriteWord(w.word,(stats[w.word]?.studyCount||0)===0));renderFavoriteSelector();};
  $('favoritePickerDone').onclick=()=>{
    save();syncFavoriteSelectorHome();
    if(unknownSelectorReturnDay){
      const targetDay=Number(unknownSelectorReturnDay);
      const selectedCount=unknownWordCountForDay(targetDay);
      if(selectedCount<1){
        alert('모르는 단어 또는 복습할 단어를 최소 1개 선택해 주세요.');
        return;
      }
      unknownSelectorReturnDay=null;
      openDay(targetDay,'learn');
      return;
    }
    goHome();
  };
}

function lexicalAllItems(kind='synonym'){
  const out=[];
  ALL_WORDS.forEach(w=>{
    const list=kind==='antonym'?antonymsOf(w):fallbackSynonymsOf(w);
    list.forEach(x=>{if(x&&x.en)out.push({en:recallText(x.en),ko:recallText(x.ko||''),source:w.word});});
  });
  return out;
}
function lexicalShuffle(arr){return shuffleDeck(arr);}
function lexicalUniqueOptions(correct, pool, key='en', count=4){
  const seen=new Set([String(correct[key]||'').toLowerCase()]);
  const others=[];
  lexicalShuffle(pool).forEach(x=>{const v=String(x[key]||'').trim();const k=v.toLowerCase();if(v&&!seen.has(k)){seen.add(k);others.push(x);}});
  return lexicalShuffle([correct,...others.slice(0,count-1)]);
}
function lexicalUsedSynonym(q){
  const info=actualSynonymInfo(q);
  if(info&&info.surface)return {en:info.surface,ko:info.ko||'',source:q.word};
  const target=recallText(q.synonymUsed||'').trim();
  if(!target)return null;
  const hit=fallbackSynonymsOf(q).find(x=>recallText(x.en).toLowerCase()===target.toLowerCase());
  return hit?{en:target,ko:hit.ko||'',source:q.word}:null;
}
function chooseLexicalQuestion(q){
  const syns=fallbackSynonymsOf(q).map(x=>({...x,source:q.word}));
  const ants=antonymsOf(q).map(x=>({...x,source:q.word}));
  const used=lexicalUsedSynonym(q);
  const types=[];
  if(syns.length)types.push('same');
  if(syns.some(x=>x.ko))types.push('meaning');
  if(used&&q.paraphrase)types.push('used');
  if(ants.length)types.push('antonym');
  if(!types.length)return null;
  const type=types[Math.floor(Math.random()*types.length)];
  if(type==='same'){
    const correct=syns[Math.floor(Math.random()*syns.length)];
    return {type,title:'같은 뜻 찾기',prompt:q.word,question:`‘${q.word}’와 의미가 가장 가까운 표현은?`,correct,options:lexicalUniqueOptions(correct,lexicalAllItems('synonym'),'en')};
  }
  if(type==='meaning'){
    const correct=syns[Math.floor(Math.random()*syns.length)];
    const pool=lexicalAllItems('synonym').filter(x=>x.ko);
    return {type,title:'유의어 뜻 맞추기',prompt:correct.en,question:`‘${correct.en}’의 뜻은?`,correct,options:lexicalUniqueOptions(correct,pool,'ko')};
  }
  if(type==='used'){
    return {type,title:'사용된 유의어 찾기',prompt:q.paraphrase,question:'패러프레이징 문장에 실제로 사용된 유의어는?',correct:used,options:lexicalUniqueOptions(used,lexicalAllItems('synonym'),'en')};
  }
  const correct=ants[Math.floor(Math.random()*ants.length)];
  return {type,title:'반의어 찾기',prompt:q.word,question:`‘${q.word}’와 반대 의미인 표현은?`,correct,options:lexicalUniqueOptions(correct,[...lexicalAllItems('antonym'),...lexicalAllItems('synonym')],'en')};
}
async function lexicalResultPlayback(q,item){
  stopSpeech();if('speechSynthesis' in window)window.speechSynthesis.cancel();
  await speakOne(item.correct.en,.82);
  if(item.type==='used'&&q.paraphrase){await new Promise(r=>setTimeout(r,250));await speakOne(q.paraphrase,.9);}
  else if(q.example){await new Promise(r=>setTimeout(r,250));await speakOne(q.example,.9);}
}
function newLexicalQuestion(){
  if(!quizDeck.length)buildQuizDeck();
  if(!quizDeck.length){
    $('qw').textContent='학습할 유의어·반의어가 없습니다.';
    $('quizMeta').textContent=quizScopeLabel()+'에서 등록된 유의어·반의어 데이터를 찾지 못했습니다.';
    $('opts').innerHTML='';$('quizFeedback').className='quizFeedback hidden';quizSessionDone=true;updateQuizProgress();return;
  }
  if(quizIndex>=quizDeck.length){showQuizFinish();return;}
  quizAnswered=false;quizCurrent=quizDeck[quizIndex];const q=quizCurrent;
  updateQuizProgress();updateQuestionNavButtons();updateQuizStats(q);
  $('quiz').classList.remove('ko-en-mode');$('quizFeedback').className='quizFeedback hidden';$('nextq').classList.remove('hidden');
  const item=chooseLexicalQuestion(q);
  if(!item){quizIndex++;newLexicalQuestion();return;}
  q.__lexicalQuestion=item;
  $('qw').textContent=item.prompt;
  $('quizMeta').textContent=`${quizScopeLabel()} · 유의어·반의어 · ${item.title} · ${quizIndex+1}/${quizDeck.length}`;
  $('opts').innerHTML=`<div class="lexQuizCard"><div class="lexQuizType">${recallEscape(item.title)}</div><div class="lexQuizPrompt">${recallEscape(item.question)}</div>${item.type==='used'?`<div class="lexQuizSentence">${recallEscape(item.prompt)}</div>`:''}<div class="lexQuizHint">정답을 선택하면 단어와 예문을 끝까지 들은 뒤 다음 문제로 이동합니다.</div></div>`+item.options.map((x,idx)=>`<button class="option lexicalOption" data-idx="${idx}">${recallEscape(item.type==='meaning'?x.ko:x.en)}</button>`).join('');
  document.querySelectorAll('#opts .lexicalOption').forEach(btn=>btn.onclick=()=>{
    if(quizAnswered)return;quizAnswered=true;
    const selected=item.options[Number(btn.dataset.idx)];
    const key=item.type==='meaning'?'ko':'en';
    const correct=recallText(selected[key]).trim().toLowerCase()===recallText(item.correct[key]).trim().toLowerCase();
    const st=stats[q.word]||(stats[q.word]={quizCorrect:0,quizWrong:0,quizStreak:0});
    document.querySelectorAll('#opts .lexicalOption').forEach((b,idx)=>{b.disabled=true;const x=item.options[idx];if(recallText(x[key]).trim().toLowerCase()===recallText(item.correct[key]).trim().toLowerCase())b.classList.add('correct');});
    if(correct){st.quizCorrect=(st.quizCorrect||0)+1;st.quizStreak=(st.quizStreak||0)+1;applyQuizReviewResult(st,true);$('quizFeedback').className='quizFeedback ok';$('quizFeedback').innerHTML=`맞았습니다!<div class="lexAnswerDetail"><b>${recallEscape(item.correct.en)}</b>${item.correct.ko?' - '+recallEscape(item.correct.ko):''}</div>`;}
    else{btn.classList.add('wrong');st.quizWrong=(st.quizWrong||0)+1;st.quizStreak=0;st.lastQuizWrong=Date.now();applyQuizReviewResult(st,false);if(!quizSessionWrong.some(x=>x.word===q.word))quizSessionWrong.push({word:q.word,meaning:q.meaning});$('quizFeedback').className='quizFeedback no';$('quizFeedback').innerHTML=`틀렸습니다.<div class="lexAnswerDetail">정답: <b>${recallEscape(item.correct.en)}</b>${item.correct.ko?' - '+recallEscape(item.correct.ko):''}</div>`;}
    save();updateQuizStats(q);quizPendingPlaybackFactory=()=>lexicalResultPlayback(q,item);startCurrentQuizResultPlayback();
  });
  if(hasStarted&&item.type!=='used')speakOne(item.prompt,.82);
}

function newq(){
  clearQuizAutoNext();
  if(quizMode==='favorite'){renderFavoriteSelector();return;}
  if(quizMode==='lexical'){newLexicalQuestion();return;}
  if(quizMode==='sentence'){
    newSentenceRecallQuestion();
    return;
  }
  if(quizMode==='recall'){
    newRecallQuestion();
    return;
  }
  if(!quizDeck.length){
    buildQuizDeck();
  }

  if(!quizDeck.length){
    $('qw').textContent='완료 🎉';
    $('quizMeta').textContent=quizScopeLabel()+' 조건에 해당하는 문제가 없습니다.';
    $('opts').innerHTML='';
    $('quizFeedback').className='quizFeedback hidden';
    $('nextq').textContent='다시하기';
    $('nextq').classList.remove('hidden');
    $('idx').textContent='0';
    $('total').textContent='0';
    $('bar').style.width='0%';
    quizSessionDone=true;
    return;
  }

  if(quizIndex >= quizDeck.length){
    showQuizFinish();
    return;
  }

  let direction=$('quizDirection').value;$('quiz').classList.toggle('ko-en-mode',direction==='koEn');
  $('quizFeedback').className='quizFeedback hidden';
  $('quizFeedback').textContent='';
  $('nextq').textContent='다음 문제';
  $('nextq').classList.remove('hidden');
  quizAnswered=false;
  quizCurrent=quizDeck[quizIndex];
  updateQuizProgress();
  updateQuestionNavButtons();

  let q=quizCurrent;
  updateQuizStats(q);
  let choicePool=quizAllWrongMode
    ? ALL_WORDS
    : ALL_WORDS.filter(x=>Number(x.newDay)===Number(quizSelectedDay));
  if(choicePool.length<4)choicePool=ALL_WORDS;
  let c=[q,...choicePool.filter(x=>x.word!==q.word).sort(()=>Math.random()-.5).slice(0,3)].sort(()=>Math.random()-.5);
  let st=stats[q.word];

  if(direction==='koEn'){
    $('qw').textContent=q.meaning;
    $('quizMeta').textContent=`${quizScopeLabel()} · 한글 뜻에 맞는 영어 단어를 고르세요 · ${quizIndex+1}/${quizDeck.length}`;
    $('opts').innerHTML=c.map(x=>`<button class="option" data-w="${x.word}">${x.word}</button>`).join('');
  }else{
    $('qw').textContent=q.word;
    $('quizMeta').textContent=`${quizScopeLabel()} · 영어 단어의 뜻을 고르세요 · ${quizIndex+1}/${quizDeck.length}`;
    $('opts').innerHTML=c.map(x=>`<button class="option" data-w="${x.word}">${x.meaning}</button>`).join('');
  }

  document.querySelectorAll('#opts .option').forEach(o=>o.onclick=()=>{
    if(quizAnswered)return;
    quizAnswered=true;
    let selected=o.dataset.w, correct=selected===q.word;
    let selectedObj=ALL_WORDS.find(x=>x.word===selected);

    document.querySelectorAll('#opts .option').forEach(x=>{
      x.disabled=true;
      if(x.dataset.w===q.word)x.classList.add('correct');
    });

    if(!correct){
      o.classList.add('wrong');
      st.quizWrong+=1;
      st.quizStreak=0;
      st.lastQuizWrong=Date.now();
      applyQuizReviewResult(st,false);
      quizSessionWrong.push({word:q.word, meaning:q.meaning});
      $('quizFeedback').innerHTML=`틀렸습니다.<br><span style="display:block;font-size:15px;margin-top:7px">선택한 답의 영어 단어</span><span style="display:block;font-size:28px;margin-top:3px">${selectedObj.word}</span><span style="display:block;font-weight:700;margin-top:4px">${selectedObj.meaning}</span><hr style="border:0;border-top:1px solid #fecaca;margin:12px 0"><span style="display:block;font-size:14px">정답</span><span style="display:block;font-size:24px;margin-top:3px">${q.word}</span><span style="display:block;font-weight:700;margin-top:4px">${q.meaning}</span>`;
      $('quizFeedback').className='quizFeedback no';
    }else{
      st.quizCorrect+=1;
      st.quizStreak=(st.quizStreak||0)+1;
      applyQuizReviewResult(st,true);
      $('quizFeedback').innerHTML=`맞았습니다!<br><span style="display:block;font-size:28px;margin-top:7px">${q.word}</span><span style="display:block;font-weight:700;margin-top:4px">${q.meaning}</span>`;
      $('quizFeedback').className='quizFeedback ok';
    }
    save();
    updateQuizStats(q);
    quizPendingPlaybackFactory=()=>choiceResultPlayback(q,selectedObj,correct);
    startCurrentQuizResultPlayback();
  });

  if(hasStarted && direction==='enKo'){
    speechSynthesis.cancel();
    speakQuizWordRepeated(q,.78);
  }
}

