// 퀴즈 화면 좌우 스와이프: 왼쪽은 다음 문제, 오른쪽은 이전 문제.
(function enableQuizSwipeNavigation(){
  const quizEl=document.getElementById('quiz');
  if(!quizEl||quizEl.dataset.swipeReady==='1')return;
  quizEl.dataset.swipeReady='1';
  let sx=0,sy=0,tracking=false,locked=false,dir=0;
  const isInteractive=target=>!!target?.closest('button,select,input,textarea,a,[role="button"],.compareSheet,.drawerPanel');

  const canQuiz=d=>{
    if(d>0)return !quizSessionDone && quizIndex<quizDeck.length-1;
    return quizIndex>0 || quizSessionDone;
  };
  const commitQuiz=d=>{
    clearQuizAutoNext?.();
    if(d>0){goToNextQuizQuestion();return true}
    const prev=$('prevq');
    if(prev){prev.click();return true}
    return false;
  };

  quizEl.addEventListener('touchstart',e=>{
    if(e.touches.length!==1||isInteractive(e.target))return;
    sx=e.touches[0].clientX;sy=e.touches[0].clientY;tracking=true;locked=false;dir=0;
  },{passive:true});
  quizEl.addEventListener('touchmove',e=>{
    if(!tracking||e.touches.length!==1)return;
    const t=e.touches[0],dx=t.clientX-sx,dy=t.clientY-sy;
    if(!locked&&Math.abs(dx)>=12&&Math.abs(dx)>=Math.abs(dy)*.82){
      dir=dx<0?1:-1;
      if(canQuiz(dir)){
        locked=window.MV_SWIPE_STANDARD_254?.begin?.({
          root:quizEl,dir,x:sx,y:sy,onCommit:commitQuiz
        })===true;
      }
    }
    if(locked){
      e.preventDefault();
      window.MV_SWIPE_STANDARD_254?.move?.(t.clientX,t.clientY);
    }
  },{passive:false});
  quizEl.addEventListener('touchend',e=>{
    if(!tracking)return;
    const t=e.changedTouches&&e.changedTouches[0];
    if(locked&&t)window.MV_SWIPE_STANDARD_254?.finalPoint?.(t.clientX,t.clientY);
    tracking=false;
    if(locked){locked=false;window.MV_SWIPE_STANDARD_254?.end?.(false)}
  },{passive:true});
  quizEl.addEventListener('touchcancel',()=>{
    tracking=false;
    if(locked){locked=false;window.MV_SWIPE_STANDARD_254?.end?.(false)}
  },{passive:true});
})();


