  ['learn','quiz','score','forget'].forEach(v=>$(v).classList.toggle('hidden',v!==tabName));
  let isLearn=tabName==='learn';$('bottom').classList.toggle('hidden',!isLearn);$('toolbar').classList.add('hidden');$('modeNote').classList.toggle('hidden',!isLearn);if(isLearn)updateLearningPlaybackButton();
