function refreshUsageRecommendation(){
  const title=$('usageRecommendTitle'),list=$('usageRecommendList');
  if(!title||!list)return;
  const due=typeof dueWordsAll==='function'?dueWordsAll().length:0;
  const weak=ALL_WORDS.filter(w=>(stats[w.word]?.quizWrong||0)>0).length;
  const favoriteCount=favs.length;
  let nextDay=1;
  for(let d=1;d<=currentCfg().days;d++){
    const p=dayProgress(d);
    if(p.learned<p.total){nextDay=d;break}
  }
  const items=[];
  if(due>0)items.push(`망각곡선에서 오늘 복습 대상 ${due}개를 먼저 확인하세요.`);
  items.push(`새 단어는 1. 학습 → DAY VOCA에서 DAY ${nextDay}부터 이어가세요.`);
  if(weak>0||favoriteCount>0){
    items.push(`2. 단어 학습 → 단어 퀴즈에서 오답 ${weak}개와 모르는 단어 ${favoriteCount}개를 복습하세요.`);
  }else{
    items.push('2. 단어 학습 → 단어 퀴즈에서 단어 맞추기 또는 단어 말하기로 확인하세요.');
  }
  items.push('3. 문장 말하기에서 문장 말하기 연습 또는 음성 녹음 학습으로 직접 말해 보세요.');
  title.textContent=due>0?'오늘은 복습부터 시작하세요':`DAY ${nextDay} 학습을 이어가세요`;
  list.innerHTML=items.map(x=>`<li>${x}</li>`).join('');
}

