function hideStandalonePages(){['configPage','usagePage','comparePage','voicePracticePage'].forEach(id=>{const el=$(id);if(el)el.classList.add('hidden')})}
let configReturnState={page:'home',scrollY:0};
function captureConfigReturnState(){
  const home=$('homePage'),day=$('dayAppPage'),myclass=$('myClassPage');
  if(myclass&&!myclass.classList.contains('hidden'))return {page:'myclass',scrollY:window.scrollY||0};
  if(day&&!day.classList.contains('hidden'))return {page:'day',scrollY:window.scrollY||0};
  if(home&&!home.classList.contains('hidden'))return {page:'home',scrollY:window.scrollY||0};
  return configReturnState||{page:'home',scrollY:0};
}
function restoreConfigReturnState(){
  const state=configReturnState||{page:'home',scrollY:0};
  $('configPage')?.classList.add('hidden');
  if(state.page==='myclass'){
    $('homePage')?.classList.add('hidden');$('dayAppPage')?.classList.add('hidden');$('myClassPage')?.classList.remove('hidden');$('myClassBottom')?.classList.remove('hidden');
  }else if(state.page==='day'){
    $('myClassPage')?.classList.add('hidden');$('myClassBottom')?.classList.add('hidden');$('homePage')?.classList.add('hidden');$('dayAppPage')?.classList.remove('hidden');
  }else{
    $('myClassPage')?.classList.add('hidden');$('myClassBottom')?.classList.add('hidden');$('dayAppPage')?.classList.add('hidden');$('homePage')?.classList.remove('hidden');
  }
  requestAnimationFrame(()=>window.scrollTo({top:Number(state.scrollY)||0,behavior:'auto'}));
}
function showConfigSavedToast(message='설정이 저장되었습니다 ✓'){
  let toast=document.getElementById('configSavedToast');
  if(!toast){
    toast=document.createElement('div');toast.id='configSavedToast';
    toast.style.cssText='position:fixed;left:50%;bottom:82px;transform:translateX(-50%);z-index:99999;background:#111827;color:#fff;padding:10px 16px;border-radius:999px;font-size:13px;font-weight:900;box-shadow:0 8px 24px rgba(15,23,42,.22);opacity:0;transition:opacity .18s ease;pointer-events:none;white-space:nowrap';
    document.body.appendChild(toast);
  }
  toast.textContent=message;toast.style.opacity='1';
  clearTimeout(window.__configSavedToastTimer);
  window.__configSavedToastTimer=setTimeout(()=>{toast.style.opacity='0'},1200);
}
function openConfiguration(){if(document.getElementById('myClassPage')&&!document.getElementById('myClassPage').classList.contains('hidden')){try{myClassHardNavigationStop?.()}catch(e){}}else stopSpeech();prepareSeparatedUsagePage();fillConfigurationForm();configReturnState=captureConfigReturnState();$('homePage').classList.add('hidden');$('dayAppPage').classList.add('hidden');$('myClassPage')?.classList.add('hidden');$('myClassBottom')?.classList.add('hidden');hideStandalonePages();$('configPage').classList.remove('hidden');window.scrollTo(0,0)}
function closeConfiguration(){stopSpeech();restoreConfigReturnState()}
function openUsagePage(){stopSpeech();prepareSeparatedUsagePage();refreshUsageRecommendation();$('homePage').classList.add('hidden');$('dayAppPage').classList.add('hidden');hideStandalonePages();$('usagePage').classList.remove('hidden');window.scrollTo(0,0)}
function closeUsagePage(){stopSpeech();$('usagePage').classList.add('hidden');$('homePage').classList.remove('hidden');window.scrollTo(0,0)}
prepareSeparatedUsagePage();
if($('openConfigBtn'))$('openConfigBtn').onclick=openConfiguration;
if($('configBackBtn'))$('configBackBtn').onclick=closeConfiguration;
if($('usageBackBtn'))$('usageBackBtn').onclick=closeUsagePage;
if($('configSaveBtn'))$('configSaveBtn').onclick=()=>{saveAppSettings({speechRate:parseFloat($('cfgSpeechRate').value),exampleRepeat:parseInt($('cfgExampleRepeat').value),patternRepeat:parseInt($('cfgPatternRepeat').value),collocationRepeat:parseInt($('cfgCollocationRepeat').value),synonymRepeat:parseInt($('cfgSynonymRepeat').value),recallDelay:parseInt($('cfgRecallDelay').value),sentenceRepeat:parseInt($('cfgSentenceRepeat').value),dayLoopSentenceRepeat:parseInt($('cfgDayLoopSentenceRepeat').value),sentenceContinuous:$('cfgSentenceContinuous').checked,sentencePause:parseInt($('cfgSentencePause').value),wordReadRepeat:parseInt($('cfgWordReadRepeat').value),continuousStudyRepeat:parseInt($('cfgContinuousStudyRepeat').value),quizWordRepeat:parseInt($('cfgQuizWordRepeat').value),quizAutoNext:$('cfgQuizAutoNext').checked,myClassAutoPlay:$('cfgMyClassAutoPlay')?.checked!==false,myClassSentenceRepeat:parseInt($('cfgMyClassSentenceRepeat')?.value||'2'),myClassPause:parseInt($('cfgMyClassPause')?.value||'700')});restoreConfigReturnState();showConfigSavedToast()};
if($('configResetBtn'))$('configResetBtn').onclick=()=>{appSettings={...APP_SETTINGS_DEFAULTS};localStorage.setItem(APP_SETTINGS_KEY,JSON.stringify(appSettings));setSpeechRate(appSettings.speechRate);fillConfigurationForm();syncContinuousStudyRepeatControl();refreshHomeConfigSummary()};
if($('cfgPlaybackPositionReset'))$('cfgPlaybackPositionReset').onclick=()=>{
  if(!confirm('저장된 전체 재생 위치를 모두 처음으로 되돌릴까요?\n학습 선택과 다른 설정은 유지됩니다.'))return;
  try{window.mv419ResetAllPlaybackPositions?.()}catch(e){try{clearSelectedProgress?.()}catch(x){}}
  showConfigSavedToast('재생 위치를 처음으로 초기화했습니다 ✓');
};

