let MV_ACTIVITY_CONTEXT='learn'; // learn | quiz | sentence | voice

function mvApplyQuizSentenceSeparation(){
  try{mvNormalizeQuizModeUI?.()}catch(e){}
  const sw=document.querySelector('.quizModeSwitch');
  const sentenceBtn=document.getElementById('quizModeSentence');
  const quizBtns=['quizModeChoice','quizModeRecall','quizModeFavorite','quizModeLexical']
    .map(id=>document.getElementById(id)).filter(Boolean);
  const filterLabel=document.querySelector('.quizFilterLabel');

  if(MV_ACTIVITY_CONTEXT==='sentence'){
    // 문장 말하기는 독립 Activity이므로 퀴즈 방식 선택 박스 자체를 표시하지 않는다.
    sw?.classList.add('hidden');
    sw?.classList.remove('mvSentenceActivityMode');
    quizBtns.forEach(b=>b.classList.add('hidden'));
    sentenceBtn?.classList.add('hidden');
    if(filterLabel)filterLabel.textContent='문장 대상';
  }else{
    sw?.classList.remove('hidden');
    sw?.classList.remove('mvSentenceActivityMode');
    quizBtns.forEach(b=>b.classList.remove('hidden'));
    sentenceBtn?.classList.add('hidden');
    if(filterLabel)filterLabel.textContent='퀴즈 대상';
  }
}
window.mvApplyQuizSentenceSeparation=mvApplyQuizSentenceSeparation;

function mvNormalizeQuizModeUI(){
  const sw=document.querySelector('.quizModeSwitch');
  if(!sw)return false;
  const order=['quizModeChoice','quizModeLexical','quizModeRecall','quizModeFavorite','quizModeSentence'];
  order.forEach(id=>{
    const el=document.getElementById(id);
    if(el)sw.appendChild(el);
  });
  const choice=document.getElementById('quizModeChoice');
  if(choice)choice.textContent='단어 맞추기';
  const lexical=document.getElementById('quizModeLexical');
  if(lexical)lexical.textContent='유의어·반의어';
  const recall=document.getElementById('quizModeRecall');
  if(recall)recall.textContent='단어 말하기';
  const favorite=document.getElementById('quizModeFavorite');
  if(favorite)favorite.textContent='모르는 단어 선택';
  return true;
}
window.mvNormalizeQuizModeUI=mvNormalizeQuizModeUI;


function mvSetActivityContext(context){
  MV_ACTIVITY_CONTEXT=String(context||'learn');
  document.documentElement.dataset.mvActivity=MV_ACTIVITY_CONTEXT;
  mvApplyQuizSentenceSeparation();
}
window.mvSetActivityContext=mvSetActivityContext;

function mvOpenStudyMode(mode){
  const m=['day','my','sori','opic','friends'].includes(mode)?mode:'day';
  mvSetActivityContext('learn');
  try{goHome()}catch(e){document.getElementById('homePage')?.classList.remove('hidden')}
  setTimeout(()=>{
    try{setHomeStudyMode(m)}catch(e){}
    const sel=m==='day'?'.daySection':m==='my'?'.myClassSection':m==='sori'?'.soriClassSection':m==='opic'?'.opicClassSection':'.friendsClassSection';
    document.querySelector(`#homePage ${sel}`)?.scrollIntoView({behavior:'smooth',block:'start'});
  },40);
}
window.mvOpenStudyMode=mvOpenStudyMode;

function mvOpenQuizActivity(day=currentDay||1){
  mvSetActivityContext('quiz');
  openDay(Number(day)||1,'quiz');
  if(quizMode==='sentence')setQuizMode('choice');
  mvApplyQuizSentenceSeparation();
  updateQuizPlaybackButton?.();
}
window.mvOpenQuizActivity=mvOpenQuizActivity;

function mvOpenSentenceSpeakingActivity(day=currentDay||1,source=null){
  // Drawer/home direct entry is standalone: no return-to-learning link.
  try{window.mvSpeakingBridgeClear183?.()}catch(e){}
  const targetDay=Number(day)||1;

  // IMPORTANT:
  // Set the shared quiz engine to sentence mode BEFORE openDay().
  // openDay('quiz') immediately calls activateDayTab('quiz') -> resetQuizSession().
  // If sentence mode is set after that reset, a word-quiz card can remain rendered
  // while only the sentence UI is visible.
  mvSetActivityContext('sentence');
  quizMode='sentence';
  quizSelectedDay=targetDay;
  quizAllWrongMode=false;

  openDay(targetDay,'quiz');

  // openDay() has now built the deck in sentence mode.
  // Only synchronize the selected sentence source; do not create a second
  // independent sentence engine.
  if(source){
    setSentenceSource(source);
  }else{
    syncSentenceSourceUI();
    updateQuizDayNav();
  }

  mvApplyQuizSentenceSeparation();
  updateQuizPlaybackButton?.();
}
window.mvOpenSentenceSpeakingActivity=mvOpenSentenceSpeakingActivity;

function mvOpenVoiceRecordingActivity(){
  mvSetActivityContext('voice');
  openVoicePracticePage();
}
window.mvOpenVoiceRecordingActivity=mvOpenVoiceRecordingActivity;

