window.mvRecordingEngineAudit=mvRecordingEngineAudit;


const __mvSetQuizMode171=setQuizMode;
setQuizMode=function(mode){
  if(MV_ACTIVITY_CONTEXT==='quiz'&&mode==='sentence')mode='choice';
  const r=__mvSetQuizMode171(mode);
  setTimeout(mvApplyQuizSentenceSeparation,0);
  return r;
};
window.setQuizMode=setQuizMode;




