async function runLessonTabs(lesson,token){
  myClassLessonNo=lesson;myClassUpdateHeader();
  const tabs=['corrections','chunks','speaking'];
  const settings=loadAppSettings(), repeat=Math.max(1,parseInt(settings.myClassSentenceRepeat||2,10)), pause=Math.max(0,parseInt(settings.myClassPause||700,10));
  for(const tab of tabs){
    if(token!==V535.runToken||MY_CLASS_PLAY.paused)return false;
    myClassTab=tab;baseRender();renderSpeakingParagraphUI();updateFullRepeatChip?.();
    await new Promise(r=>setTimeout(r,35));
    const items=myClassPlaybackItems();
    for(let idx=0;idx<items.length;idx++){
      if(token!==V535.runToken||MY_CLASS_PLAY.paused)return false;
      const item=items[idx];MY_CLASS_PLAY.index=idx;MY_CLASS_PLAY.currentText=item.text;myClassFocus(item.el);
      const rc=MY_CLASS_PLAY.repeatCurrent?999999:repeat;
      for(let r=0;r<rc;r++){
        if(token!==V535.runToken||MY_CLASS_PLAY.paused)return false;
        const unit=item.paragraph?'문단':'문장';
        myClassSetStatus(`수업 ${lesson} · ${tab==='corrections'?'핵심 교정':tab==='chunks'?'Chunk':'말하기'} · ${idx+1}/${items.length} · ${unit} ${MY_CLASS_PLAY.repeatCurrent?'∞':`${r+1}/${repeat}`}`,true);
        await speakBlock(item.text,item.paragraph);
        if(token!==V535.runToken||MY_CLASS_PLAY.paused)return false;
        await new Promise(res=>setTimeout(res,pause));
      }
    }
  }
  return true;
}
async function legacyStartSelectedLessons(){
  const lessons=V535.selected.length?V535.selected:getSelected();
  if(!lessons.length){alert('반복할 MY 수업을 하나 이상 체크해 주세요.');return}
  V535.multiRun=true;V535.runToken++;
  const token=V535.runToken;
  stopSpeech();MY_CLASS_PLAY.active=true;MY_CLASS_PLAY.paused=false;MY_CLASS_PLAY.repeatCurrent=false;myClassSyncButtons();
  document.getElementById('homePage')?.classList.add('hidden');
  document.getElementById('dayAppPage')?.classList.add('hidden');
  if(typeof hideStandalonePages==='function')hideStandalonePages();
  document.getElementById('myClassPage')?.classList.remove('hidden');
  document.getElementById('myClassBottom')?.classList.remove('hidden');
  while(token===V535.runToken&&!MY_CLASS_PLAY.paused){
    for(const n of lessons){
      if(!(await runLessonTabs(n,token)))return;
    }
    myClassSetStatus(`체크한 수업 ${lessons.join(', ')} 1회 완료 · 다시 반복합니다`,true);
    await new Promise(r=>setTimeout(r,500));
  }
}
