/* ===== V5.3.275 · BACKGROUND PLAYBACK POSITION STANDARD =====
   Shared by MY / SORI / OPIC / FRIENDS. A background transition may finish only the
   repetition already in progress; it never runs ahead into unrelated items.
   On return:
   - unfinished repetition -> same item / same repetition
   - finished repetition but more repeats remain -> same item / next repeat
   - finished item -> next item
*/
const MV_BG_PLAYBACK_207={
  hidden:false,
  wasActive:false,
  mode:'idle',
  course:'my',
  cursor:0,
  rep:0,
  reps:1,
  repDone:false,
  itemDone:false,
  nextCursor:0,
  itemKey:'',
  infiniteItem:null,
  restorePending:false,
  lastHiddenAt:0
};
window.MV_BG_PLAYBACK_207=MV_BG_PLAYBACK_207;

function m536BgCheckpoint207(patch={}){
  Object.assign(MV_BG_PLAYBACK_207,patch);
  return MV_BG_PLAYBACK_207;
}
function m536BgShouldYield207(){
  return !!(MV_BG_PLAYBACK_207.hidden || document.visibilityState==='hidden');
}
window.m536BgCheckpoint207=m536BgCheckpoint207;

async function m536RunFull(startAt=0,startRep=0){
  const course=M536?.course||ACTIVE_STUDY_COURSE;
  m536StopLegacyPlaybackOnly();
  const list=m536BuildPlaylist(course);
  if(!list.length){
    // v5.3.275: in overall repeat, empty favorite-only course = skip to next course.
    if(window.MV_ALL_REPEAT_219?.active && typeof window.MV_COURSE_ONCE_COMPLETE_219==='function'){
      const done=window.MV_COURSE_ONCE_COMPLETE_219;
      window.MV_COURSE_ONCE_COMPLETE_219=null;
      setTimeout(()=>done(course),80);
      return false;
    }
    const courseName=(typeof studyCourseConfig==='function'?studyCourseConfig(ACTIVE_STUDY_COURSE)?.title:null)||'학습';
    alert(`반복할 ${courseName} 콘텐츠가 없습니다.`);
    return false;
  }

  M536.playlist=list;
  M536.cursor=Math.max(0,Math.min(list.length-1,Number(startAt)||0));
  M536.mode='full';M536.infiniteKey='';M536.infiniteItem=null;M536.busy=true;
  const token=++M536.token;
  const hardEpoch=MY_CLASS_HARD_STOP_EPOCH;
  MY_CLASS_PLAY.active=true;MY_CLASS_PLAY.paused=false;
  m536Unlock();
  myClassSyncButtons?.();

  let firstItem=true;
  while(token===M536.token && hardEpoch===MY_CLASS_HARD_STOP_EPOCH && M536.mode==='full'){
    const item=M536.playlist[M536.cursor];
    if(!item)return;
    try{window.mv419TrackRunningItem?.(course,M536.cursor,item)}catch(e){}
    const el=await m536RenderItemForFull255(item);
    if(token!==M536.token || hardEpoch!==MY_CLASS_HARD_STOP_EPOCH || M536.mode!=='full')return;
    const cfg=loadAppSettings();
    const reps=Math.max(1,parseInt(cfg.myClassSentenceRepeat||2,10));
    const pause=Math.max(0,parseInt(cfg.myClassPause||700,10));
    let repStart=firstItem?Math.max(0,Math.min(reps-1,Number(startRep)||0)):0;
    firstItem=false;

    m536BgCheckpoint207({
      mode:'full',course,cursor:M536.cursor,rep:repStart,reps,
      repDone:false,itemDone:false,nextCursor:(M536.cursor+1)%M536.playlist.length,
      itemKey:m536ItemKey(item),infiniteItem:null
    });

    for(let r=repStart;r<reps;r++){
      if(token!==M536.token || hardEpoch!==MY_CLASS_HARD_STOP_EPOCH || M536.mode!=='full')return;

      m536BgCheckpoint207({
        mode:'full',course,cursor:M536.cursor,rep:r,reps,
        repDone:false,itemDone:false,nextCursor:(M536.cursor+1)%M536.playlist.length,
        itemKey:m536ItemKey(item)
      });

      MY_CLASS_PLAY.currentText=item.text;MY_CLASS_PLAY.currentEl=el;
      myClassSetStatus?.(`전체 반복 · 수업 ${item.lesson} · ${m536Label(item.tab)} ${item.index+1} · ${item.paragraph?'문단':'문장'} ${r+1}/${reps}`,true);

      await m536SpeakItem(item,el,()=>token===M536.token && hardEpoch===MY_CLASS_HARD_STOP_EPOCH && M536.mode==='full');
      if(token!==M536.token || hardEpoch!==MY_CLASS_HARD_STOP_EPOCH || M536.mode!=='full')return;

      m536BgCheckpoint207({rep:r+1,repDone:true});

      if(pause)await m536Sleep(pause);
      if(token!==M536.token || hardEpoch!==MY_CLASS_HARD_STOP_EPOCH || M536.mode!=='full')return;

      // Do not advance multiple learning items in the background.
      if(m536BgShouldYield207() && r<reps-1){
        m536BgCheckpoint207({cursor:M536.cursor,rep:r+1,itemDone:false,repDone:true});
        M536.busy=false;
        return;
      }
    }

    const next=(M536.cursor+1)%M536.playlist.length;
    m536BgCheckpoint207({
      cursor:M536.cursor,rep:reps,reps,repDone:true,itemDone:true,nextCursor:next,
      itemKey:m536ItemKey(item)
    });
    M536.cursor=next;

    // v5.3.275: optional outer-orchestrator completion hook.
    // Dormant during normal MY/SORI/OPIC/FRIENDS repeat, so individual repeat behavior is unchanged.
    if(next===0 && typeof window.MV_COURSE_ONCE_COMPLETE_219==='function'){
      const done=window.MV_COURSE_ONCE_COMPLETE_219;
      window.MV_COURSE_ONCE_COMPLETE_219=null;
      M536.busy=false;
      M536.mode='idle';
      MY_CLASS_PLAY.active=false;
      MY_CLASS_PLAY.paused=true;
      setTimeout(()=>done(course),80);
      return;
    }

    // v5.3.275: deterministic integrated controller - one playlist per course.
    if(window.MV_ALL_REPEAT_215?.active && window.MV_MIXED_COURSE_ONCE_215 && next===0){
      window.MV_MIXED_COURSE_ONCE_215=false;
      M536.busy=false;
      M536.mode='idle';
      MY_CLASS_PLAY.active=false;
      MY_CLASS_PLAY.paused=true;
      setTimeout(()=>window.allRepeatAdvance215?.(),80);
      return;
    }

    // Legacy v5.3.275 hook retained outside v215 sessions.
    if(window.MV_ALL_REPEAT_209?.active && window.MV_MIXED_COURSE_ONCE_209 && next===0){
      window.MV_MIXED_COURSE_ONCE_209=false;
      M536.busy=false;
      M536.mode='idle';
      MY_CLASS_PLAY.active=false;
      MY_CLASS_PLAY.paused=true;
      setTimeout(()=>window.allRepeatAdvance209?.(),80);
      return;
    }

    // Current item is complete: next visible resume must begin at exactly the next item.
    if(m536BgShouldYield207()){
      M536.busy=false;
      return;
    }
  }
}

async function m536RunInfinite(item){
  const lockedItem={...item,course:m536ItemCourse(item)};
  const lockedKey=m536ItemKey(lockedItem);
  const lockedCourse=lockedItem.course;

  m536StopLegacyPlaybackOnly();
  M536.course=lockedCourse;
  ACTIVE_STUDY_COURSE=lockedCourse;
  M536.mode='infinite';
  M536.infiniteItem=lockedItem;
  M536.infiniteKey=lockedKey;
  M536.busy=true;

  const token=++M536.token;
  const hardEpoch=MY_CLASS_HARD_STOP_EPOCH;
  MY_CLASS_PLAY.active=true;
  MY_CLASS_PLAY.paused=false;
  m536Unlock();

  const el=m536RenderItem(lockedItem);
  m536SyncInfinityButtons();
  try{syncMyClassInfinityVisuals?.()}catch(e){}

  const pause=Math.max(0,parseInt(loadAppSettings().myClassPause||700,10));
  let n=1;
  const alive=()=>(
    token===M536.token &&
    hardEpoch===MY_CLASS_HARD_STOP_EPOCH &&
    M536.mode==='infinite' &&
    M536.course===lockedCourse &&
    M536.infiniteKey===lockedKey
  );

  m536BgCheckpoint207({
    mode:'infinite',course:lockedCourse,cursor:Number(M536.cursor)||0,
    rep:0,reps:Infinity,repDone:false,itemDone:false,itemKey:lockedKey,
    infiniteItem:{...lockedItem}
  });

  while(alive()){
    m536BgCheckpoint207({
      mode:'infinite',course:lockedCourse,rep:n-1,repDone:false,itemDone:false,
      itemKey:lockedKey,infiniteItem:{...lockedItem}
    });

    myClassSetStatus?.(
      `∞ 무한 반복 · ${studyCourseConfig(lockedCourse)?.title||lockedCourse} · ${m536Label(lockedItem.tab)} ${lockedItem.index+1} · ${lockedItem.paragraph?'문단 전체':'현재 문장'} · ${n}회`,
      true
    );

    await m536SpeakItem(lockedItem,el,alive);
    if(!alive())return;

    m536BgCheckpoint207({rep:n,repDone:true,itemDone:false});
    n++;

    if(pause){
      await m536Sleep(pause);
      if(!alive())return;
    }

    // Infinite repeat always stays on the same item; yield while backgrounded.
    if(m536BgShouldYield207()){
      M536.busy=false;
      return;
    }
  }
}

function m536RestoreAfterBackground207(){
  const s=MV_BG_PLAYBACK_207;
  if(!s.restorePending || !s.wasActive || s.hidden)return false;
  s.restorePending=false;

  const page=document.getElementById('myClassPage');
  if(!page || page.classList.contains('hidden'))return false;
  if(!STUDY_COURSES?.[s.course])return false;

  // Stop any stale async/TTS callback that survived Android app switching.
  M536.token++;
  try{stopSpeech()}catch(e){}
  try{window.speechSynthesis?.cancel()}catch(e){}
  try{if(window.speechSynthesis?.paused)window.speechSynthesis.resume()}catch(e){}
  m536StopLegacyPlaybackOnly();

  ACTIVE_STUDY_COURSE=s.course;
  M536.course=s.course;
  m536Unlock();

  if(s.mode==='infinite' && s.infiniteItem){
    const item={...s.infiniteItem,course:s.course};
    M536.mode='infinite';
    M536.infiniteItem=item;
    M536.infiniteKey=m536ItemKey(item);
    M536.busy=true;
    m536RenderItem(item);
    setTimeout(()=>m536RunInfinite(item),80);
    return true;
  }

  if(s.mode==='full'){
    const list=m536BuildPlaylist(s.course);
    if(!list.length)return false;

    let cursor=0, rep=0;
    if(s.itemDone){
      cursor=Math.max(0,Math.min(list.length-1,Number(s.nextCursor)||0));
      rep=0;
    }else{
      // Resolve by key first so selection/tab changes cannot send playback elsewhere.
      const byKey=list.findIndex(x=>m536ItemKey(x)===s.itemKey);
      cursor=byKey>=0?byKey:Math.max(0,Math.min(list.length-1,Number(s.cursor)||0));
      rep=Math.max(0,Number(s.rep)||0);
    }

    M536.mode='full';
    M536.busy=true;
    setTimeout(()=>m536RunFull(cursor,rep),80);
    return true;
  }
  return false;
}
window.m536RestoreAfterBackground207=m536RestoreAfterBackground207;

document.addEventListener('visibilitychange',()=>{
  const s=MV_BG_PLAYBACK_207;
  if(document.visibilityState==='hidden'){
    const active=(M536.mode==='full'||M536.mode==='infinite') && !!MY_CLASS_PLAY.active;
    s.hidden=true;
    s.wasActive=active;
    s.mode=active?M536.mode:'idle';
    s.course=M536.course||ACTIVE_STUDY_COURSE||'my';
    s.lastHiddenAt=Date.now();
    s.restorePending=active;
    if(active && s.mode==='infinite' && M536.infiniteItem){
      s.infiniteItem={...M536.infiniteItem};
      s.itemKey=m536ItemKey(M536.infiniteItem);
    }
  }else{
    s.hidden=false;
    if(s.restorePending && s.wasActive){
      setTimeout(m536RestoreAfterBackground207,120);
    }
  }
});

window.addEventListener('pageshow',()=>{
  MV_BG_PLAYBACK_207.hidden=false;
  if(MV_BG_PLAYBACK_207.restorePending && MV_BG_PLAYBACK_207.wasActive){
    setTimeout(m536RestoreAfterBackground207,140);
  }
});
window.addEventListener('focus',()=>{
  if(document.visibilityState==='visible' && MV_BG_PLAYBACK_207.restorePending && MV_BG_PLAYBACK_207.wasActive){
    setTimeout(m536RestoreAfterBackground207,160);
  }
});

function m536StartCourse(course=ACTIVE_STUDY_COURSE){
  M536_TOGGLE_STATE.pausedMode='idle';
  M536_TOGGLE_STATE.pausedInfiniteItem=null;
  const selectedCourse=(typeof STUDY_COURSES!=='undefined' && STUDY_COURSES[course])?course:'my';

  stopAllMyClassPlayback(true);

  // Lock playback to the selected course AFTER the old session is fully stopped.
  ACTIVE_STUDY_COURSE=selectedCourse;
  M536.course=selectedCourse;

  const chosen=m536Lessons(selectedCourse);
  if(!chosen.length){
    const courseName=(typeof studyCourseConfig==='function'?studyCourseConfig(selectedCourse)?.title:null)||'학습';
    alert(`반복할 ${courseName} 항목을 하나 이상 체크해 주세요.`);
    return;
  }

  m536Unlock();
  M536.resumeWasFull=false;M536.resumeCursor=0;
  document.getElementById('homePage')?.classList.add('hidden');
  document.getElementById('dayAppPage')?.classList.add('hidden');
  try{hideStandalonePages?.()}catch(e){}
  document.getElementById('myClassPage')?.classList.remove('hidden');
  document.getElementById('myClassBottom')?.classList.remove('hidden');

  myClassLessonNo=chosen[0]||1;
  myClassTab=studyCourseOrder(selectedCourse)[0]||'corrections';
  myClassUpdateHeader?.();
  renderMyClass();

  m536RunFull(0);
}
function m536StartFull(){
  return m536StartCourse(ACTIVE_STUDY_COURSE);
}


/* ===== V5.3.189 · CANONICAL INFINITY ENTRY ===== */
function m536ToggleInfiniteByKey(key){
  const parts=String(key||'').split('|');
  if(parts.length!==4)return false;
  const [course,lesson,tab,index]=parts;
  if(!STUDY_COURSES?.[course])return false;
  const item=m536MakeItem(course,Number(lesson),tab,Number(index));
  if(!item)return false;

  ACTIVE_STUDY_COURSE=course;
  M536.course=course;
  m536ToggleInfinite(Number(lesson),tab,Number(index),course);
  return true;
}
window.m536ToggleInfiniteByKey=m536ToggleInfiniteByKey;

function m536ToggleInfinite(lesson,tab,index,course=m536ActiveCourse()){
  try{myClassClearSpeakingSentenceHighlight()}catch(e){}
  try{mvDomClearHighlight?.()}catch(e){}

  const c=String(course||'my');
  const item=m536MakeItem(c,lesson,tab,index);
  if(!item)return;
  const key=m536ItemKey(item);

  // Same button = stop infinite; resume full only if it was entered from full.
  if(M536.mode==='infinite' && M536.infiniteKey===key){
    const shouldResume=!!M536.returnToFull;
    const resumeAt=Number.isFinite(M536.resumeCursor)?M536.resumeCursor:0;

    M536.token++;
    try{stopSpeech()}catch(e){}
    try{window.speechSynthesis?.cancel()}catch(e){}
    M536.mode='idle';
    M536.infiniteKey='';
    M536.infiniteItem=null;
    M536.busy=false;
    MY_CLASS_PLAY.active=false;
    MY_CLASS_PLAY.paused=true;
    MY_CLASS_PLAY.repeatCurrent=false;
    MY_TITLE_INFINITY_KEY='';
    MY_CLASS_INFINITY_VISUAL_KEY='';

    m536SyncInfinityButtons();
    syncMyClassTitleInfinityButtons?.();
    myClassSyncButtons?.();

    if(shouldResume){
      M536.resumeWasFull=false;
      M536.returnToFull=false;
      M536.course=c;
      ACTIVE_STUDY_COURSE=c;
      myClassSetStatus?.('∞ 집중 해제 · 전체 반복 이어서 재생',true);
      setTimeout(()=>m536RunFull(resumeAt),40);
    }else{
      myClassSetStatus?.('∞ 무한 반복 해제',false);
      try{stopRepeatWakeSession?.()}catch(e){}
    }
    return;
  }

  // Capture full-repeat return position before stopping full.
  const cameFromFull=M536.mode==='full';
  if(cameFromFull){
    M536.resumeCursor=Number.isFinite(M536.cursor)?M536.cursor:0;
    M536.resumeWasFull=true;
    M536.returnToFull=true;
  }else if(M536.mode!=='infinite'){
    M536.resumeWasFull=false;
    M536.returnToFull=false;
  }

  // Stop current modern loop and every legacy loop.
  M536.token++;
  try{stopSpeech()}catch(e){}
  try{window.speechSynthesis?.cancel()}catch(e){}
  m536StopLegacyPlaybackOnly();

  M536.course=c;
  ACTIVE_STUDY_COURSE=c;
  M536.mode='infinite';
  M536.infiniteKey=key;
  M536.infiniteItem=item;
  M536.busy=true;
  MY_CLASS_INFINITY_VISUAL_KEY=key;
  MY_TITLE_INFINITY_KEY=key;

  syncMyClassTitleInfinityButtons?.();
  syncMyClassInfinityVisuals?.();
  myClassSyncButtons?.();
  m536RunInfinite(item);
}


