// a.m. / p.m. 때문에 문장 자체가 '2 a.' + 'm.'으로 갈라지는 문제 수정.
const m536PrevSplit=myClassSplitSentences;
myClassSplitSentences=function(text){
  const src=String(text||'')
    .replace(/\b(\d{1,2})\s*a\.m\./gi,'$1 __AM__')
    .replace(/\b(\d{1,2})\s*p\.m\./gi,'$1 __PM__');
  const arr=m536PrevSplit(src);
  return arr.map(x=>x.replace(/__AM__/g,'a.m.').replace(/__PM__/g,'p.m.'));
};

// TTS에서는 2 a.m. → "two A M"으로 보내 마침표에서 끊지 않게 한다.
const m536PrevNormalize=normalizeTextForTTS;
normalizeTextForTTS=function(text,lang){
  let t=String(text||'');
  if(/^en/i.test(lang||'en-US')){
    const nums={1:'one',2:'two',3:'three',4:'four',5:'five',6:'six',7:'seven',8:'eight',9:'nine',10:'ten',11:'eleven',12:'twelve'};
    t=t.replace(/\b(1[0-2]|[1-9])\s*a\.?\s*m\.?\b/gi,(_,n)=>`${nums[Number(n)]||n} A M`)
       .replace(/\b(1[0-2]|[1-9])\s*p\.?\s*m\.?\b/gi,(_,n)=>`${nums[Number(n)]||n} P M`);
  }
  return m536PrevNormalize(t,lang);
};

