// MY 수업 재생 중 다른 내비게이션을 누르면 클릭 순간 즉시 정지.
document.addEventListener('click',(e)=>{
  const myPage=document.getElementById('myClassPage');
  if(!myPage || myPage.classList.contains('hidden'))return;

  const nav=e.target.closest(
    '#myClassHomeBtn,.drawerItem,.bottomNav button,[data-page],[data-nav],#navLearn,#navQuiz,#navHome'
  );
  if(!nav)return;
  // V5.3.281: HOME is a resumable checkpoint command, not a hard navigation stop.
  if(nav.id==='myClassHomeBtn')return;

  // MY 수업 내부의 무한반복/재생 컨트롤은 제외.
  if(nav.closest('#myClassPage') &&
     (nav.classList.contains('myTitleInfinityBtn') ||
      nav.classList.contains('myInfinityBtn') ||
      nav.id==='myClassPlayPause'))return;

  try{stopAllMyClassPlayback(true)}catch(err){}
},true);


// ===== V5.3.189 MY 수업 HARD navigation stop =====
function myClassHardNavigationStop(){
  try{stopAllMyClassPlayback(true)}catch(e){}
  // Samsung Internet TTS cancel 안정성을 위해 짧게 한 번 더 취소한다.
  try{window.speechSynthesis?.cancel()}catch(e){}
  setTimeout(()=>{try{window.speechSynthesis?.cancel()}catch(e){}},60);
  setTimeout(()=>{try{window.speechSynthesis?.cancel()}catch(e){}},180);
}
window.myClassHardNavigationStop=myClassHardNavigationStop;

document.addEventListener('click',(e)=>{
  const page=document.getElementById('myClassPage');
  if(!page || page.classList.contains('hidden'))return;

  const target=e.target.closest(
    '#myClassHomeBtn,#myClassConfigBtn,.myClassTab,.drawerItem,'+
    '#navHome,#navLearn,#navQuiz,.bottomNav button,[data-drawer-action],[data-page],[data-nav]'
  );
  // V5.3.281: bottom HOME is handled by the unified pause+checkpoint controller.
  if(target && target.id!=='myClassHomeBtn') myClassHardNavigationStop();
},true);


// V5.3.189: renderMyClass가 버튼 DOM을 새로 만들어도 active 색상을 즉시 복원한다.
function installInfinityVisualObserver(){
  const root=document.getElementById('myClassContent');
  if(!root || root.dataset.infinityVisualObserver==='1')return;
  root.dataset.infinityVisualObserver='1';
  let raf=0;
  new MutationObserver(()=>{
    cancelAnimationFrame(raf);
    raf=requestAnimationFrame(()=>{try{syncMyClassInfinityVisuals()}catch(e){}});
  }).observe(root,{childList:true,subtree:true});
}
setTimeout(installInfinityVisualObserver,0);


// V5.3.189: 무한 반복 상태 표시 heartbeat.
// 브라우저/DOM 재렌더 방식과 무관하게 반복 중에는 250ms마다 active UI를 복구한다.
if(!window.__mvInfinityHeartbeat){
  window.__mvInfinityHeartbeat=setInterval(()=>{
    if(document.hidden)return;
    const page=document.getElementById('myClassPage');
    if(!page || page.classList.contains('hidden'))return;
    try{
      if(typeof M536!=='undefined' && M536.mode==='infinite'){
        const key=String(M536.infiniteKey||'');
        if(key){
          MY_TITLE_INFINITY_KEY=key;
          const b=document.querySelector(`.myTitleInfinityBtn[data-inf-key="${CSS.escape(key)}"]`);
          if(b){
            b.classList.add('active');
            b.dataset.repeatState='on';
            b.setAttribute('aria-pressed','true');
            b.style.setProperty('background','linear-gradient(135deg,#4f46e5,#7c3aed)','important');
            b.style.setProperty('color','#fff','important');
            b.style.setProperty('border-color','#6d28d9','important');
            b.style.setProperty('box-shadow','0 6px 16px rgba(109,40,217,.32)','important');
            b.querySelectorAll('*').forEach(x=>x.style.setProperty('color','#fff','important'));
            const f=b.querySelector('.myInfFocus'); if(f)f.textContent='반복 중';
          }
        }
      }
    }catch(e){}
  },250);
}





















