/* ===== V5.3.189 · DAY-ONLY PLAYBACK PANEL STANDARD ===== */
function mvPlaceDayPlaybackPanel(){
  const panel=document.querySelector('#homePage .homePlaybackCard');
  const day=document.querySelector('#homePage .daySection');
  if(!panel||!day)return false;
  if(panel.parentElement!==day){
    const head=day.querySelector(':scope > .sectionHead');
    if(head)head.insertAdjacentElement('afterend',panel);
    else day.prepend(panel);
  }
  panel.dataset.studyScope='day';
  return panel.parentElement===day;
}
window.mvPlaceDayPlaybackPanel=mvPlaceDayPlaybackPanel;

