  function allRepeatAdvance209(){
    const s=MV_ALL_REPEAT_209;
    if(!s.active||s.advancing)return;
    s.advancing=true;
    setTimeout(()=>{
      if(!s.active)return;
      const fresh=[...s.queue];
      if(!fresh.length){allRepeatStop209();alert('전체 반복할 학습 항목을 하나 이상 선택해 주세요.');return}
      s.queue=fresh;
      let currentIndex=s.queue.indexOf(s.current);
      s.index=currentIndex>=0?currentIndex+1:s.index+1;
      if(s.index>=s.queue.length){s.index=0;s.cycle++}
      const next=s.queue[s.index];
      s.advancing=false;
      allRepeatRunCourse209(next);
    },120);
  }
