  /* ===== V5.3.275 · DETERMINISTIC CROSS-COURSE REPEAT CONTROLLER ===== */
  const MV_ALL_REPEAT_215={active:false,queue:[],index:0,current:'',cycle:0,advancing:false,token:0,snapshots:null};
